window.SAT_DATA = window.SAT_DATA || {};
(window.SAT_DATA.vocabQuestions = window.SAT_DATA.vocabQuestions || []).push(
{"id": "vq-md-acceptable", "wordId": "md-acceptable", "skill": "words-in-context", "stem": "In early trials of the water-filtration prototype, engineers judged the device's performance ______ though hardly remarkable: it met every minimum safety threshold set by regulators yet fell well short of the efficiency the team had hoped to achieve.", "choices": [{"text": "acceptable", "why": "The colon supplies the definition: the device 'met every minimum safety threshold' while remaining unremarkable, so it was satisfactory—meeting required standards without exceeding them."}, {"text": "exceptional", "why": "Fails on intensity: exceptional means outstandingly good, which 'hardly remarkable' and 'fell well short' directly contradict.", "tag": "too-broad"}, {"text": "deficient", "why": "Reversed: deficient means failing to meet a required standard, but the device satisfied every regulatory threshold.", "tag": "reversed"}, {"text": "irrelevant", "why": "Unsupported: irrelevant means unrelated to the matter at hand, and the passage evaluates the device's quality, not its pertinence.", "tag": "unsupported"}], "answer": 0},
{"id": "vq-md-accessory", "wordId": "md-accessory", "skill": "words-in-context", "stem": "For Victorian gentlemen, the pocket watch often functioned less as an essential instrument than as a fashionable ______: suspended from a gleaming chain across the waistcoat, it was added to an ensemble chiefly to signal taste and prosperity.", "choices": [{"text": "staple", "why": "Reversed: a staple is a basic, essential item, but the passage explicitly contrasts the watch with an 'essential instrument.'", "tag": "reversed"}, {"text": "accessory", "why": "The contrast 'less as an essential instrument than as' plus 'added to an ensemble' to enhance attractiveness defines an accessory: a nonessential item that makes something more appealing."}, {"text": "heirloom", "why": "Unsupported: an heirloom is an object passed down through generations, and the passage says nothing about inheritance.", "tag": "unsupported"}, {"text": "commodity", "why": "Wrong domain: a commodity is a good bought and sold in commerce, but the passage concerns adornment of an outfit, not trade.", "tag": "unsupported"}], "answer": 1},
{"id": "vq-md-accomplishment", "wordId": "md-accomplishment", "skill": "words-in-context", "stem": "Completing the transcontinental railroad in 1869 was a formidable ______: laborers had blasted tunnels through the granite of the Sierra Nevada and laid nearly two thousand miles of track, finishing a project that many engineers had dismissed as impossible.", "choices": [{"text": "accomplishment", "why": "The clues 'Completing' and 'finishing a project... dismissed as impossible' describe the successful attainment of a difficult goal—an accomplishment."}, {"text": "aspiration", "why": "Reversed in time: an aspiration is a hope not yet realized, but the passage describes work already completed.", "tag": "reversed"}, {"text": "coincidence", "why": "Unsupported: a coincidence is an accidental co-occurrence of events, but the railroad resulted from deliberate, arduous labor.", "tag": "unsupported"}, {"text": "formality", "why": "Fails on intensity: a formality is a routine act done for procedure's sake, contradicting 'formidable' and the project's near-impossible difficulty.", "tag": "too-specific"}], "answer": 0},
{"id": "vq-md-acknowledge", "wordId": "md-acknowledge", "skill": "words-in-context", "stem": "In the published correction, the research team took care to ______ the statistical errors that had inflated their original findings, openly conceding what earlier press releases had strenuously minimized.", "choices": [{"text": "dispute", "why": "Reversed: to dispute is to contest or deny, but the appositive says the team was 'openly conceding' the errors.", "tag": "reversed"}, {"text": "overstate", "why": "Unsupported: to overstate is to exaggerate, but the team was admitting the errors accurately, not inflating them further.", "tag": "unsupported"}, {"text": "acknowledge", "why": "The phrase 'openly conceding what earlier press releases had... minimized' restates the blank: the team admitted the truth of the errors."}, {"text": "lament", "why": "Fails on precision: to lament is to express sorrow or regret, but the passage supports admission of fact, not an expression of grief.", "tag": "unsupported"}], "answer": 2},
{"id": "vq-md-acquired", "wordId": "md-acquired", "skill": "words-in-context", "stem": "Perfect pitch was long assumed to be an innate gift, but recent studies suggest the ability can be ______ through intensive ear training, since young students who received systematic instruction in early childhood developed it at strikingly high rates.", "choices": [{"text": "inherited", "why": "Reversed: inherited means received genetically at birth, but the contrast with 'innate gift' and the clue 'through intensive ear training' point to learning, not heredity.", "tag": "reversed"}, {"text": "acquired", "why": "The contrast marker 'but' opposes 'innate gift,' and 'through intensive ear training' shows the ability is gained by effort and experience—acquired."}, {"text": "forfeited", "why": "Reversed in direction: forfeited means lost or surrendered, but the students gained the ability rather than losing it.", "tag": "reversed"}, {"text": "simulated", "why": "Unsupported: simulated means imitated or faked, but the students genuinely 'developed' the ability, not a mere imitation of it.", "tag": "unsupported"}], "answer": 1},
{"id": "vq-md-advantageous", "wordId": "md-advantageous", "skill": "words-in-context", "stem": "Ecologists studying alpine wildflowers found that early snowmelt proved ______ for seedlings on south-facing slopes: plants there gained several additional weeks of growing time and produced markedly more seeds than their late-emerging counterparts.", "choices": [{"text": "detrimental", "why": "Reversed: detrimental means harmful, but the seedlings gained growing time and produced more seeds—clear benefits.", "tag": "reversed"}, {"text": "inevitable", "why": "Unsupported: inevitable means unavoidable, and the passage evaluates whether the snowmelt helped the plants, not whether it was certain to occur.", "tag": "unsupported"}, {"text": "advantageous", "why": "The colon lists the benefits—extra 'growing time' and 'markedly more seeds'—so early snowmelt was favorable and beneficial for these seedlings."}, {"text": "profitable", "why": "Wrong domain: profitable means yielding financial gain, but the benefits here are biological (growth and seed production), not monetary.", "tag": "too-specific"}], "answer": 2},
{"id": "vq-md-aggressive", "wordId": "md-aggressive", "skill": "words-in-context", "stem": "In negotiations, the firm's new director abandoned the cautious, measured approach of her predecessor; her ______ tactics—making bold demands and refusing to yield an inch—unsettled competitors who had grown comfortable with a gentler style.", "choices": [{"text": "timid", "why": "Reversed: timid means shy and hesitant, contradicting 'bold demands' and 'refusing to yield.'", "tag": "reversed"}, {"text": "aggressive", "why": "'Bold demands' and 'refusing to yield an inch,' set against a 'gentler style,' point to forceful, dominating behavior."}, {"text": "conciliatory", "why": "Reversed: conciliatory tactics aim to appease and soften conflict, the opposite of the forceful pressure she applies.", "tag": "reversed"}, {"text": "impulsive", "why": "Impulsive means acting on sudden whim, but her deliberate 'tactics' are calculated, not rash; nothing marks them as spontaneous.", "tag": "unsupported"}], "answer": 1},
{"id": "vq-md-analogy", "wordId": "md-analogy", "skill": "words-in-context", "stem": "To explain how electric current flows through a circuit, the physics teacher offered a homely ______: the electrons streaming along a wire, she said, are much like water coursing through a pipe, driven forward by pressure.", "choices": [{"text": "metaphor", "why": "A metaphor calls one thing another outright, but the teacher draws an explicit, explanatory comparison signaled by 'like.'", "tag": "too-specific"}, {"text": "analogy", "why": "An explanatory comparison—electrons in a wire are 'like' water in a pipe—offered to clarify is exactly an analogy."}, {"text": "refutation", "why": "A refutation disproves a claim, but nothing here is being disproved.", "tag": "unsupported"}, {"text": "hyperbole", "why": "Hyperbole is deliberate exaggeration for effect, absent from this plain, clarifying comparison.", "tag": "unsupported"}], "answer": 1},
{"id": "vq-md-angular", "wordId": "md-angular", "skill": "words-in-context", "stem": "Critics noted how sharply the architect's late style broke from the soft curves of his early work; his final museum was aggressively ______, all jutting corners and hard-edged planes meeting at severe, deliberate intervals.", "choices": [{"text": "sinuous", "why": "Reversed: sinuous means winding and curved, the opposite of the sharp corners described and echoing the rejected 'soft curves.'", "tag": "reversed"}, {"text": "jagged", "why": "Jagged means roughly and irregularly notched, but the design shows clean, deliberate geometric angles, not raggedness.", "tag": "too-specific"}, {"text": "angular", "why": "'Jutting corners and hard-edged planes meeting at severe... intervals' describe a form built from sharp angles."}, {"text": "rounded", "why": "Reversed: rounded means smoothly curved, contradicting the hard edges and jutting corners.", "tag": "reversed"}], "answer": 2},
{"id": "vq-md-antagonistic", "wordId": "md-antagonistic", "skill": "words-in-context", "stem": "Although the two chemists had once collaborated warmly, years of bitter disputes over credit left their relationship openly ______: they now contradicted each other at every conference and pointedly refused to cite each other's published work.", "choices": [{"text": "cordial", "why": "Reversed: cordial means warm and friendly, the opposite of the open conflict described.", "tag": "reversed"}, {"text": "collaborative", "why": "Reversed: collaborative means cooperative and mutually supportive, contradicting their public contradicting and snubbing.", "tag": "reversed"}, {"text": "competitive", "why": "Competitive means eager to outdo one another, which falls short of the open hostility shown by refusing to cite each other.", "tag": "too-specific"}, {"text": "antagonistic", "why": "Contradicting each other publicly and refusing to acknowledge each other's work shows active opposition and hostility."}], "answer": 3},
{"id": "vq-md-anthropology", "wordId": "md-anthropology", "skill": "words-in-context", "stem": "Margaret Mead's fieldwork in Samoa helped establish ______ as a discipline that joins intimate, long-term observation of a living community's kinship customs and rituals with broader questions about how human cultures develop and diverge.", "choices": [{"text": "archaeology", "why": "Too specific in the wrong direction: archaeology studies past societies through material remains such as artifacts and ruins, but Mead observed a living community directly.", "tag": "too-specific"}, {"text": "anthropology", "why": "The appositive after 'discipline' describes the study of human societies, customs, and cultural development—exactly what anthropology is."}, {"text": "linguistics", "why": "Too specific: linguistics is the study of language alone, whereas the passage describes research into kinship, ritual, and cultural development generally.", "tag": "too-specific"}, {"text": "physiology", "why": "Physiology concerns the functioning of living organisms' bodies; nothing in the passage involves biological processes rather than cultural ones.", "tag": "unsupported"}], "answer": 1},
{"id": "vq-md-anticipate", "wordId": "md-anticipate", "skill": "words-in-context", "stem": "Because storm surges tend to follow well-documented patterns of wind and tide, forecasters can now ______ coastal flooding many hours before it begins, giving low-lying towns precious time to move residents and equipment to higher ground.", "choices": [{"text": "prevent", "why": "To prevent is to stop something from happening, but the passage says the flooding still 'begins'; the forecasters only give advance warning.", "tag": "unsupported"}, {"text": "recall", "why": "Reversed in time: to recall is to remember something past, while the passage is about foreseeing an event that has not yet occurred.", "tag": "reversed"}, {"text": "anticipate", "why": "The phrase 'many hours before it begins,' supported by 'well-documented patterns,' shows the forecasters predict the flooding in advance—the meaning of anticipate."}, {"text": "observe", "why": "To observe is to watch something as it happens, which contradicts 'before it begins'; the passage describes prediction, not eyewitness monitoring.", "tag": "unsupported"}], "answer": 2},
{"id": "vq-md-anticipating", "wordId": "md-anticipating", "skill": "words-in-context", "stem": "______ a rush of orders once the celebrated critic's review appeared, the small press printed three times its usual run and hired seasonal staff—preparations that proved prescient when the novel sold out within a week.", "choices": [{"text": "Recalling", "why": "Reversed in time: recalling means remembering something past, but the rush of orders had not yet happened when the press prepared for it.", "tag": "reversed"}, {"text": "Dismissing", "why": "Reversed: dismissing means rejecting something as unimportant; a press that dismissed the coming demand would not have tripled its print run.", "tag": "reversed"}, {"text": "Witnessing", "why": "Witnessing means seeing an event occur, but the press acted before the review appeared and before any orders arrived.", "tag": "unsupported"}, {"text": "Anticipating", "why": "The press prepared in advance for a surge that later materialized—'preparations that proved prescient'—so the blank must mean expecting and readying for something."}], "answer": 3},
{"id": "vq-md-artifice", "wordId": "md-artifice", "skill": "words-in-context", "stem": "Critics eventually recognized that the memoirist's disarming frankness was itself a calculated ______: by freely confessing trivial faults, she steered readers away from scrutinizing the book's far larger fabrications.", "choices": [{"text": "blunder", "why": "Reversed: a blunder is a careless mistake, but the passage calls the tactic 'calculated' and shows it worked as intended.", "tag": "reversed"}, {"text": "courtesy", "why": "A courtesy is a polite gesture; nothing in the passage concerns politeness—the frankness served to conceal deception.", "tag": "unsupported"}, {"text": "disclosure", "why": "She did disclose minor faults, but the sentence's point is that the openness was a deceptive design, which 'disclosure' fails to capture.", "tag": "true-but-irrelevant"}, {"text": "artifice", "why": "The colon reveals a cunning scheme—confessing small faults to hide 'far larger fabrications'—so the blank must mean a clever trick used to deceive."}], "answer": 3},
{"id": "vq-md-artisan", "wordId": "md-artisan", "skill": "words-in-context", "stem": "Guild records from fourteenth-century Bruges show that before earning the title of master, a ______ was required to spend nearly a decade perfecting handcraft techniques—hammering silver, cutting stone, or binding books—under the scrutiny of the town's most accomplished practitioners.", "choices": [{"text": "artisan", "why": "The dash introduces skilled manual crafts—hammering silver, cutting stone, binding books—so the blank must name a skilled worker who makes things by hand."}, {"text": "laborer", "why": "Too general: a laborer is anyone who does physical work, missing the specialized, mastered craft skill the decade of training implies.", "tag": "too-broad"}, {"text": "merchant", "why": "A merchant buys and sells goods; the passage describes making objects by hand, not trading them.", "tag": "unsupported"}, {"text": "patron", "why": "A patron financially supports craftspeople or the arts; nothing in the passage involves funding rather than practicing the craft.", "tag": "unsupported"}], "answer": 0},
{"id": "vq-md-asserted", "wordId": "md-asserted", "skill": "words-in-context", "stem": "In a 1912 address, Alfred Wegener boldly ______ that the continents had once formed a single landmass, a claim he defended without hesitation even as prominent geologists dismissed the mechanism he proposed for their drift.", "choices": [{"text": "conceded", "why": "Reversed: to concede is to admit something reluctantly under pressure, but Wegener is confidently advancing a claim, not yielding to opponents.", "tag": "reversed"}, {"text": "insinuated", "why": "Wrong manner: to insinuate is to hint at something indirectly and slyly, but \"boldly\" and \"without hesitation\" describe an open, direct declaration.", "tag": "too-specific"}, {"text": "asserted", "why": "The cues \"boldly\" and \"a claim he defended without hesitation\" show a confident declaration, which is exactly what asserted means."}, {"text": "reiterated", "why": "To reiterate is to state something again, but the passage mentions no earlier declaration for Wegener to repeat.", "tag": "unsupported"}], "answer": 2},
{"id": "vq-md-attainable", "wordId": "md-attainable", "skill": "words-in-context", "stem": "Skeptics had long derided the goal of eradicating the disease as a fantasy, but after vaccination campaigns eliminated it from three continents in a single decade, public health officials began describing global eradication as genuinely ______.", "choices": [{"text": "inevitable", "why": "Too strong: inevitable means certain to happen, but the campaigns' success shows only that the goal can be reached, not that it is guaranteed.", "tag": "too-broad"}, {"text": "quixotic", "why": "Reversed: quixotic means hopelessly impractical, which restates the skeptics' \"fantasy\" view that the new evidence overturns.", "tag": "reversed"}, {"text": "effortless", "why": "Overstates the case: decade-long vaccination campaigns show the goal takes enormous work; achievable does not mean easy.", "tag": "too-broad"}, {"text": "attainable", "why": "The contrast marker \"but\" pivots from \"fantasy\" to evidence of real progress, so the blank must mean achievable—capable of being reached."}], "answer": 3},
{"id": "vq-md-atypical", "wordId": "md-atypical", "skill": "words-in-context", "stem": "In most spiral galaxies, the arms trail behind the direction of rotation; NGC 4622, whose outer arms appear to wind forward instead, is therefore considered ______—an exception that has prompted astronomers to revisit their models of galactic dynamics.", "choices": [{"text": "defective", "why": "Defective implies a flaw or malfunction; the galaxy departs from the usual pattern but is not described as broken or damaged.", "tag": "unsupported"}, {"text": "representative", "why": "Reversed: representative means typical of the group, contradicting both \"instead\" and the appositive \"an exception.\"", "tag": "reversed"}, {"text": "atypical", "why": "The contrast between \"most spiral galaxies\" and NGC 4622's opposite-winding arms, capped by the appositive \"an exception,\" requires a word meaning not conforming to the usual pattern."}, {"text": "archaic", "why": "Archaic means ancient or old-fashioned; the passage concerns the galaxy's unusual structure, not its age.", "tag": "unsupported"}], "answer": 2},
{"id": "vq-md-beneficiary-of", "wordId": "md-beneficiary-of", "skill": "words-in-context", "stem": "Economic historians portray Duluth as a clear ______ the 1870 rail link: within a decade of the line's completion, the town's grain shipments had increased twentyfold and its population had more than tripled.", "choices": [{"text": "casualty of", "why": "Reversed: a casualty of something is harmed by it, but the colon details dramatic gains, not damage.", "tag": "reversed"}, {"text": "beneficiary of", "why": "The colon lists advantages that followed the rail link—shipments up twentyfold, population tripled—so the town is a recipient of the link's benefits."}, {"text": "architect of", "why": "An architect of something designs or creates it; the passage shows the town receiving the link's effects, not building the railway.", "tag": "unsupported"}, {"text": "precursor of", "why": "A precursor of something comes before it, but the town's growth followed the line's completion rather than preceding it.", "tag": "unsupported"}], "answer": 1},
{"id": "vq-md-blemish", "wordId": "md-blemish", "skill": "words-in-context", "stem": "Before the auction, conservators examined the Renaissance panel under raking light for any ______—a speck of discoloration, a faint scuff, a pinpoint of flaking paint—since even a slight surface imperfection could lower the work's value considerably.", "choices": [{"text": "blemish", "why": "The dashes list tiny marks, and \"slight surface imperfection\" glosses the blank exactly: a small flaw that spoils appearance."}, {"text": "fissure", "why": "Too severe: a fissure is a major crack or split, but the passage concerns minute surface marks like specks and scuffs.", "tag": "too-broad"}, {"text": "embellishment", "why": "An embellishment is a decorative addition meant to beautify, not a defect that lowers a work's value.", "tag": "unsupported"}, {"text": "signature", "why": "Examiners might also look for a signature, but the items listed are flaws that reduce value, not marks of authorship.", "tag": "true-but-irrelevant"}], "answer": 0},
{"id": "vq-md-catalog", "wordId": "md-catalog", "skill": "words-in-context", "stem": "During the three-year expedition, the botanists set out to ______ every plant species in the valley, recording each one's location, height, and flowering season in a meticulously ordered register that others could later consult.", "choices": [{"text": "catalog", "why": "The detail of recording each species in 'a meticulously ordered register' matches making a systematic list or record."}, {"text": "tally", "why": "Too narrow: to tally is merely to count totals, but the botanists record detailed descriptive information, not just numbers.", "tag": "too-specific"}, {"text": "uproot", "why": "To uproot is to pull plants up; the botanists document the plants, not remove them.", "tag": "unsupported"}, {"text": "overlook", "why": "Reversed: to overlook is to fail to notice, the opposite of carefully recording every species.", "tag": "reversed"}], "answer": 0},
{"id": "vq-md-census", "wordId": "md-census", "skill": "words-in-context", "stem": "Every ten years the government conducts a nationwide ______, sending workers to record how many people live in each household so that legislative seats and public funds can be apportioned fairly across regions.", "choices": [{"text": "referendum", "why": "A referendum is a public vote on a specific question, not a count of how many people live in each household.", "tag": "unsupported"}, {"text": "poll", "why": "Too narrow: a poll samples the opinions of a subset, whereas the passage describes a complete tally of the whole population.", "tag": "too-specific"}, {"text": "census", "why": "Recording how many people live in each household nationwide is precisely an official count or survey of the population."}, {"text": "audit", "why": "An audit is an examination of financial records, not a population count, so it falls outside the passage's domain.", "tag": "too-specific"}], "answer": 2},
{"id": "vq-md-challenged", "wordId": "md-challenged", "skill": "words-in-context", "stem": "When the graduate student presented data that flatly contradicted the long-accepted model, she effectively ______ the theory that had guided the field for decades, forcing senior researchers to defend assumptions they had never before been asked to justify.", "choices": [{"text": "endorsed", "why": "Reversed: to endorse is to approve, but the student's contradictory data disputes the theory rather than backing it.", "tag": "reversed"}, {"text": "revised", "why": "Too narrow: to revise is to alter or edit; the student calls the theory's validity into question, she does not amend it.", "tag": "too-specific"}, {"text": "illustrated", "why": "To illustrate is to give supporting examples; the passage shows her contesting the theory, not exemplifying it.", "tag": "unsupported"}, {"text": "challenged", "why": "Presenting contradictory data that forces researchers to defend their assumptions shows she questioned and disputed the theory's validity."}], "answer": 3},
{"id": "vq-md-characteristic", "wordId": "md-characteristic", "skill": "words-in-context", "stem": "The zoologist argued that the crescent marking above each eye was the defining ______ of the species: no closely related population displayed it, so the marking alone allowed field researchers to distinguish the animals at a glance.", "choices": [{"text": "characteristic", "why": "A defining quality unique to the species that lets researchers tell it apart is exactly a distinctive feature or trait."}, {"text": "anomaly", "why": "Too narrow: an anomaly is a deviation or exception, but the marking is a consistent, defining quality of every member of the species.", "tag": "too-specific"}, {"text": "quirk", "why": "A quirk is a minor, incidental peculiarity, not the species-defining feature the passage emphasizes.", "tag": "too-specific"}, {"text": "habitat", "why": "A habitat is the environment where an animal lives, which is unrelated to a physical marking used for identification.", "tag": "unsupported"}], "answer": 0},
{"id": "vq-md-choreographer", "wordId": "md-choreographer", "skill": "words-in-context", "stem": "The ______ spent months arranging every leap and turn of the ballet, deciding exactly where each dancer would stand and how the ensemble would move together before the company ever set foot on the rehearsal stage.", "choices": [{"text": "composer", "why": "A composer arranges music, not the physical movement of dancers, so the role is in the wrong domain.", "tag": "unsupported"}, {"text": "choreographer", "why": "Designing every leap, turn, and position of the dancers is precisely the work of the person who composes the sequence of dance movements."}, {"text": "conductor", "why": "A conductor leads the orchestra's musicians; the passage concerns arranging the dancers' steps, not directing the music.", "tag": "unsupported"}, {"text": "director", "why": "Too broad: a director oversees a whole production, but the passage specifies designing the dance movements in particular.", "tag": "too-broad"}], "answer": 1},
{"id": "vq-md-collaboration", "wordId": "md-collaboration", "skill": "words-in-context", "stem": "The breakthrough vaccine emerged not from a single laboratory but from close ______ among dozens of institutions on three continents, each freely sharing its data, samples, and expertise in pursuit of one common goal.", "choices": [{"text": "competition", "why": "Reversed: competition is rivalry, but the institutions freely share resources toward a shared aim.", "tag": "reversed"}, {"text": "coordination", "why": "Too narrow: coordination is the logistical arranging of activities, not the joint creative effort of sharing data and expertise.", "tag": "too-specific"}, {"text": "isolation", "why": "Reversed: isolation means working separately, the opposite of institutions working jointly across continents.", "tag": "reversed"}, {"text": "collaboration", "why": "Many institutions sharing data and expertise toward a common goal is exactly a cooperative effort or joint partnership."}], "answer": 3},
{"id": "vq-md-confined-to", "wordId": "md-confined-to", "skill": "words-in-context", "stem": "For decades physicians believed the fever was ______ tropical ports, appearing only in towns where ships from the equator docked; the later discovery of cases deep in the arid interior forced them to abandon that comfortable assumption.", "choices": [{"text": "exempt from", "why": "To be exempt from something is to be free of it, but the fever supposedly occurred in the ports, not spared from them.", "tag": "reversed"}, {"text": "derived from", "why": "'Derived from' names an origin, yet the passage stresses where the disease appeared, not where it came from.", "tag": "unsupported"}, {"text": "confined to", "why": "'Appearing only in towns where ships docked' marks a strict boundary, so the fever was limited or restricted to those ports."}, {"text": "typical of", "why": "'Typical of' means characteristic, but it fails to capture the exclusivity that 'only' establishes.", "tag": "too-broad"}], "answer": 2},
{"id": "vq-md-conform-to", "wordId": "md-conform-to", "skill": "words-in-context", "stem": "The regulatory agency does not reward a new drug for its novelty; before approval, each compound must ______ the strict safety thresholds printed in the pharmacopeia, matching every published benchmark for purity and dosage.", "choices": [{"text": "conform to", "why": "'Matching every published benchmark' shows the compound must comply with or adhere to the thresholds."}, {"text": "deviate from", "why": "To deviate from a standard is to depart from it, the opposite of matching every benchmark.", "tag": "reversed"}, {"text": "detract from", "why": "To detract from is to diminish; nothing suggests the drug reduces the thresholds.", "tag": "unsupported"}, {"text": "account for", "why": "'Account for' means to explain or make up a portion of, not to satisfy a required standard.", "tag": "unsupported"}], "answer": 0},
{"id": "vq-md-connection", "wordId": "md-connection", "skill": "words-in-context", "stem": "The historian resisted the temptation to view the two uprisings as isolated events; combing through private letters and shipping records, she traced a clear ______ between them, showing how organizers in one city had corresponded with and inspired those in the other.", "choices": [{"text": "divide", "why": "A divide is a separation, the opposite of the link the correspondence reveals.", "tag": "reversed"}, {"text": "coincidence", "why": "A coincidence implies no real relationship, yet the letters show one group deliberately inspired the other.", "tag": "reversed"}, {"text": "connection", "why": "'Organizers had corresponded with and inspired' the others establishes a relationship or link between the events."}, {"text": "hierarchy", "why": "A hierarchy is a ranked ordering, which the passage never establishes between the two cities.", "tag": "unsupported"}], "answer": 2},
{"id": "vq-md-construct", "wordId": "md-construct", "skill": "words-in-context", "stem": "Working only from scattered fossil fragments, the paleontologist set out to ______ a complete model of the extinct reptile, fitting each recovered bone into a supporting scaffold that would eventually reveal how the animal once stood and moved.", "choices": [{"text": "dismantle", "why": "To dismantle is to take apart, the opposite of assembling bones into a complete model.", "tag": "reversed"}, {"text": "excavate", "why": "To excavate is to dig fossils out of the ground, an earlier stage than assembling the recovered bones.", "tag": "too-specific"}, {"text": "catalogue", "why": "To catalogue is merely to list items, not to build them into a structured whole.", "tag": "unsupported"}, {"text": "construct", "why": "'Fitting each bone into a scaffold' to form 'a complete model' defines the blank as to build by putting parts together."}], "answer": 3},
{"id": "vq-md-contingent-on", "wordId": "md-contingent-on", "skill": "words-in-context", "stem": "The foundation made clear that the second installment of funding was in no way guaranteed; its release would be ______ the team's demonstrated progress, disbursed only if the first year's results met the milestones both parties had agreed upon.", "choices": [{"text": "indifferent to", "why": "'Indifferent to' means unaffected by, but the funding depends directly on the team's progress.", "tag": "reversed"}, {"text": "contingent on", "why": "'Disbursed only if the results met the milestones' shows the release is dependent or conditional on that progress."}, {"text": "prior to", "why": "'Prior to' marks time order, whereas the passage describes a condition, not a sequence.", "tag": "unsupported"}, {"text": "detrimental to", "why": "'Detrimental to' means harmful to, which reverses the supportive relationship between funding and progress.", "tag": "reversed"}], "answer": 1},
{"id": "vq-md-contradiction", "wordId": "md-contradiction", "skill": "words-in-context", "stem": "Careful listeners caught the flaw at once: the witness's account contained a glaring ______, for she claimed to have been sound asleep at midnight and yet also insisted she had watched the entire argument unfold in the hallway at that very hour.", "choices": [{"text": "understatement", "why": "An understatement deliberately minimizes something, but the witness's problem is two claims that cannot both be true.", "tag": "unsupported"}, {"text": "digression", "why": "A digression is a wandering aside; the flaw here is a clash between statements, not straying off topic.", "tag": "unsupported"}, {"text": "contradiction", "why": "Claiming to be asleep 'and yet also' to have watched the argument sets two statements in direct opposition."}, {"text": "concession", "why": "A concession is an admission that grants a point, not a conflict between incompatible claims.", "tag": "unsupported"}], "answer": 2},
{"id": "vq-md-compelling", "wordId": "md-compelling", "skill": "words-in-context", "stem": "The paleontologist's hypothesis had once been dismissed as speculation, but the discovery of fossilized nests containing both adults and hatchlings offered ______ evidence that the dinosaurs cared for their young, and even longtime skeptics found the argument difficult to refute.", "choices": [{"text": "circumstantial", "why": "Circumstantial evidence is indirect and inconclusive, yet the passage says even skeptics could not refute it, implying strong, direct persuasion.", "tag": "too-specific"}, {"text": "tangential", "why": "Tangential means only marginally relevant, but the fossils bear directly on the claim about parental care.", "tag": "unsupported"}, {"text": "compelling", "why": "That the evidence convinced 'even longtime skeptics' and was 'difficult to refute' shows it was highly convincing—the meaning of compelling."}, {"text": "provisional", "why": "Provisional means tentative and subject to change, but the evidence is presented as decisive.", "tag": "reversed"}], "answer": 2},
{"id": "vq-md-comprises", "wordId": "md-comprises", "skill": "words-in-context", "stem": "The archipelago ______ more than seven thousand islands, ranging from vast, densely populated landmasses to tiny outcrops of rock that vanish beneath the waves at high tide, yet the nation governs them all under a single constitution.", "choices": [{"text": "comprises", "why": "The whole (the archipelago) is made up of its parts (the seven thousand islands), the standard whole-comprises-parts relation."}, {"text": "constitutes", "why": "Parts constitute a whole, so the islands constitute the archipelago, not the reverse; used here it inverts the part-whole relationship.", "tag": "reversed"}, {"text": "excludes", "why": "Excludes means to leave out, but the archipelago contains the islands rather than omitting them.", "tag": "reversed"}, {"text": "resembles", "why": "Resembles means to look like, but the archipelago is composed of the islands, not merely similar to them.", "tag": "unsupported"}], "answer": 0},
{"id": "vq-md-counterpart", "wordId": "md-counterpart", "skill": "words-in-context", "stem": "When trade negotiations resumed, the American finance minister spent hours on the telephone with her ______ in Tokyo, the official who held the very same portfolio in the Japanese cabinet and faced an almost identical set of pressures at home.", "choices": [{"text": "rival", "why": "Means an opponent or competitor, whereas the passage stresses an equivalent official, not an adversary.", "tag": "unsupported"}, {"text": "subordinate", "why": "Means a person of lower rank, but the Tokyo official holds 'the very same portfolio,' an equal position.", "tag": "reversed"}, {"text": "counterpart", "why": "'The official who held the very same portfolio' in the other government is a corresponding equivalent."}, {"text": "predecessor", "why": "Means one who previously held a post, not the person occupying the equivalent role elsewhere at the same time.", "tag": "too-specific"}], "answer": 2},
{"id": "vq-md-created", "wordId": "md-created", "skill": "words-in-context", "stem": "Frustrated that no existing instrument could produce the sounds she imagined, the composer worked with an engineer for three years and eventually ______ an entirely new electronic keyboard, the first device of its kind ever to exist.", "choices": [{"text": "dismantled", "why": "Means took apart, the opposite of bringing something into being.", "tag": "reversed"}, {"text": "imitated", "why": "Means copied an existing model, whereas the passage stresses a wholly original device.", "tag": "reversed"}, {"text": "restored", "why": "Means returned something to a former condition, but there was no prior version to bring back.", "tag": "too-specific"}, {"text": "created", "why": "'An entirely new electronic keyboard, the first device of its kind ever to exist' signals bringing something into existence."}], "answer": 3},
{"id": "vq-md-criticize", "wordId": "md-criticize", "skill": "words-in-context", "stem": "Though the essayist admired the novel's ambition, she did not hesitate to ______ it, devoting three full pages to the wooden dialogue, the implausible ending, and the many faults she believed the author had failed to correct.", "choices": [{"text": "commend", "why": "Means to praise, the opposite of pointing out faults.", "tag": "reversed"}, {"text": "criticize", "why": "'Devoting three full pages to ... faults' expresses disapproval and identifies shortcomings."}, {"text": "analyze", "why": "Means to examine in detail without necessarily passing negative judgment, but the passage is explicitly fault-finding.", "tag": "too-broad"}, {"text": "endorse", "why": "Means to give approval or support, contrary to the disapproval expressed.", "tag": "reversed"}], "answer": 1},
{"id": "vq-md-decisive", "wordId": "md-decisive", "skill": "words-in-context", "stem": "The Battle of Yorktown proved ______ in the American Revolution: the British surrender there effectively ended major fighting and settled the war's outcome in favor of the colonists, leaving little doubt about the final result.", "choices": [{"text": "protracted", "why": "Reversed: protracted means drawn out, contradicting a surrender that quickly ended the fighting.", "tag": "reversed"}, {"text": "ceremonial", "why": "Unsupported: ceremonial means merely formal, ignoring that the battle actually settled the war.", "tag": "unsupported"}, {"text": "decisive", "why": "'Effectively ended major fighting and settled the war's outcome' defines a conclusive, outcome-determining event."}, {"text": "contentious", "why": "Unsupported: contentious means provoking dispute, which the passage never suggests about the battle.", "tag": "unsupported"}], "answer": 2},
{"id": "vq-md-defends", "wordId": "md-defends", "skill": "words-in-context", "stem": "In her closing essay, the scholar ______ the controversial novel against its detractors, arguing point by point that the criticisms leveled at its fractured structure misread the author's deliberate intentions.", "choices": [{"text": "abandons", "why": "Reversed: to abandon is to give up on, contradicting arguing on the novel's behalf.", "tag": "reversed"}, {"text": "defends", "why": "'Against its detractors, arguing... the criticisms misread' shows the scholar is protecting the novel."}, {"text": "summarizes", "why": "Unsupported: to summarize is merely to condense, not to protect against attack.", "tag": "unsupported"}, {"text": "concedes", "why": "Reversed: to concede is to admit the critics are right, the opposite of countering them.", "tag": "reversed"}], "answer": 1},
{"id": "vq-md-depiction", "wordId": "md-depiction", "skill": "words-in-context", "stem": "The gallery praised the young painter's ______ of rural poverty: her canvas represents the weary tenant farmers so vividly that viewers feel they are standing in the dusty field alongside them.", "choices": [{"text": "depiction", "why": "'Her canvas represents the tenant farmers so vividly' matches depiction, a representation or showing."}, {"text": "concealment", "why": "Reversed: concealment is hiding, opposite of a vivid public representation.", "tag": "reversed"}, {"text": "critique", "why": "Unsupported: a critique is an evaluation, not the pictorial representation the passage praises.", "tag": "unsupported"}, {"text": "acquisition", "why": "Unsupported: acquisition is the act of obtaining, unrelated to how the subject is portrayed.", "tag": "unsupported"}], "answer": 0},
{"id": "vq-md-derived-from", "wordId": "md-derived-from", "skill": "words-in-context", "stem": "Many modern medicines are ______ natural sources: aspirin, for example, traces its origins to a compound first obtained from the bark of the willow tree, which healers had used for centuries.", "choices": [{"text": "immune to", "why": "Unsupported: to be immune to something is to be unaffected by it, not to originate in it.", "tag": "unsupported"}, {"text": "opposed to", "why": "Unsupported: to be opposed to is to be against, illogical for medicines and their sources.", "tag": "unsupported"}, {"text": "derived from", "why": "'Traces its origins to a compound first obtained from' matches derived from, originating in a source."}, {"text": "identical to", "why": "Unsupported: identical to asserts sameness, not origin, and a medicine is not the same as its source.", "tag": "unsupported"}], "answer": 2},
{"id": "vq-md-detachment", "wordId": "md-detachment", "skill": "words-in-context", "stem": "A skilled documentary filmmaker must balance compassion with ______: however moving her subjects' stories may be, she cannot allow personal feeling to distort her clear-eyed presentation of the facts.", "choices": [{"text": "sentiment", "why": "Emotional feeling—the very thing she must guard against, so it points in the wrong direction.", "tag": "reversed"}, {"text": "urgency", "why": "A pressing need for haste; the passage concerns objectivity, not time pressure.", "tag": "unsupported"}, {"text": "indifference", "why": "A total lack of concern; but she still feels compassion, so this word overshoots to not caring at all.", "tag": "too-broad"}, {"text": "detachment", "why": "The contrast with 'compassion' and the need to keep 'personal feeling' from distorting the facts calls for objective distance."}], "answer": 3},
{"id": "vq-md-diffuse", "wordId": "md-diffuse", "skill": "words-in-context", "stem": "Public-health researchers set out to measure how quickly rumors ______ through a densely populated city, tracking the way a single overheard remark could reach many thousands of residents within a matter of hours.", "choices": [{"text": "condense", "why": "To become more concentrated or compact—the opposite of moving outward through a population.", "tag": "reversed"}, {"text": "linger", "why": "To remain in one place; this contradicts the passage's emphasis on the rumor's movement across the city.", "tag": "unsupported"}, {"text": "diffuse", "why": "A single remark 'reaching many thousands of residents' means it spreads widely over a large area and population."}, {"text": "erupt", "why": "To burst out suddenly; it captures intensity but not the gradual spread of a rumor across a large group.", "tag": "too-specific"}], "answer": 2},
{"id": "vq-md-diminish", "wordId": "md-diminish", "skill": "words-in-context", "stem": "As the glacier retreated higher up the valley year after year, the volume of meltwater feeding the region's main river began to ______, leaving the farmers downstream with a steadily shrinking supply for their thirsty fields.", "choices": [{"text": "diminish", "why": "'A steadily shrinking supply' makes clear the volume of water becomes less and less over time."}, {"text": "surge", "why": "To increase suddenly and powerfully—the reverse of the shrinking supply the passage describes.", "tag": "reversed"}, {"text": "stagnate", "why": "To stop flowing or grow stale; but the passage describes a decrease in quantity, not a loss of movement.", "tag": "too-specific"}, {"text": "meander", "why": "To follow a winding course; it describes a river's path rather than its dwindling volume.", "tag": "unsupported"}], "answer": 0},
{"id": "vq-md-disagreeable", "wordId": "md-disagreeable", "skill": "words-in-context", "stem": "The reviewer praised the novel's unflinching honesty even while conceding that its narrator is thoroughly ______: petty, rude, and quick to hurl insults at anyone who dares offer him the slightest kindness.", "choices": [{"text": "charismatic", "why": "Charming and magnetically likable—the opposite of the petty rudeness the list of traits describes.", "tag": "reversed"}, {"text": "disagreeable", "why": "'Petty, rude, and quick to hurl insults' spells out a personality that is unpleasant and unlikable."}, {"text": "reserved", "why": "Quiet and restrained; the narrator is loud and insulting, not withdrawn.", "tag": "unsupported"}, {"text": "eccentric", "why": "Unconventional or odd; oddness alone does not capture the hostility the passage details.", "tag": "too-broad"}], "answer": 1},
{"id": "vq-md-discovered", "wordId": "md-discovered", "skill": "words-in-context", "stem": "While clearing out a long-neglected storeroom in the museum's basement, a graduate student ______ a bundle of correspondence that scholars had assumed was destroyed during the war, opening an entirely new line of research.", "choices": [{"text": "misplaced", "why": "To lose track of something—the opposite of coming upon letters that had been assumed lost.", "tag": "reversed"}, {"text": "discovered", "why": "Coming upon a long-lost bundle 'assumed destroyed' means the student found and uncovered it for the first time."}, {"text": "forged", "why": "To create a counterfeit; nothing suggests the letters are fakes rather than genuine finds.", "tag": "unsupported"}, {"text": "inherited", "why": "To receive through a bequest; but she chanced upon the letters while cleaning, not by inheritance.", "tag": "too-specific"}], "answer": 1},
{"id": "vq-md-diverting", "wordId": "md-diverting", "skill": "words-in-context", "stem": "Although the novel tackles grave questions about mortality, its playful footnotes and comic digressions make the reading experience unexpectedly ______, prompting far more chuckles than its somber subject would seem to allow.", "choices": [{"text": "tedious", "why": "Tedious means tiresome and boring, the reverse of an experience that prompts chuckles.", "tag": "reversed"}, {"text": "engrossing", "why": "Engrossing means deeply absorbing; the passage points to amusement and laughter, not intense absorption.", "tag": "unsupported"}, {"text": "solemn", "why": "Solemn means grave and serious, which contradicts the playful, comic tone described.", "tag": "reversed"}, {"text": "diverting", "why": "The clues 'playful,' 'comic,' and 'more chuckles' establish that the reading is amusing and entertaining, the meaning of diverting."}], "answer": 3},
{"id": "vq-md-dormant", "wordId": "md-dormant", "skill": "words-in-context", "stem": "Buried beneath the frozen soil, the seeds can remain ______ for decades, their metabolism nearly halted, until a rare thaw finally sends the signal that prompts them to sprout.", "choices": [{"text": "flourishing", "why": "Flourishing means actively thriving and growing, the reverse of seeds whose metabolism is 'nearly halted.'", "tag": "reversed"}, {"text": "volatile", "why": "Volatile means unstable or liable to sudden change; nothing in the passage suggests instability, only suspended inactivity.", "tag": "unsupported"}, {"text": "dormant", "why": "The phrase 'metabolism nearly halted... until a thaw prompts them to sprout' describes a temporarily inactive state that later resumes, which is exactly dormant."}, {"text": "extinct", "why": "Extinct means permanently died out; it is tempting for inactivity but the seeds later sprout, so their state is only temporary, not final.", "tag": "reversed"}], "answer": 2},
{"id": "vq-md-doubted", "wordId": "md-doubted", "skill": "words-in-context", "stem": "When the young astronomer first announced that the faint smudge was an entire galaxy beyond our own, her senior colleagues openly ______ the claim, insisting that such an object surely lay well within the boundaries of the Milky Way.", "choices": [{"text": "endorsed", "why": "Endorsed means approved or supported, the opposite of colleagues who insist her claim is mistaken.", "tag": "reversed"}, {"text": "verified", "why": "Verified means confirmed as true, contradicting the colleagues' insistence that she was wrong.", "tag": "reversed"}, {"text": "resented", "why": "Resented means felt bitterness toward; it is tempting given professional rivalry, but the clue shows they challenged the truth of her claim, not begrudged her.", "tag": "true-but-irrelevant"}, {"text": "doubted", "why": "Because the colleagues 'insisted' the object lay elsewhere, they questioned the reliability of her claim, which is what doubted means."}], "answer": 3},
{"id": "vq-md-elicit", "wordId": "md-elicit", "skill": "words-in-context", "stem": "By presenting infants with brightly colored puppets, the researchers hoped to ______ a measurable response, such as a turn of the head or a widening of the eyes, that would reveal what the babies were able to perceive.", "choices": [{"text": "elicit", "why": "The researchers use puppets in order to draw out an observable reaction from the infants, which is precisely what elicit means."}, {"text": "suppress", "why": "Suppress means to hold back or stifle; the researchers want to bring a response out, not prevent one.", "tag": "reversed"}, {"text": "fabricate", "why": "Fabricate means to invent or falsify; the scientists seek a genuine reaction that reveals perception, not a manufactured one.", "tag": "unsupported"}, {"text": "anticipate", "why": "Anticipate means to expect in advance; it is tempting but describes predicting a response rather than drawing one out.", "tag": "unsupported"}], "answer": 0},
{"id": "vq-md-dislodge", "wordId": "md-dislodge", "skill": "words-in-context", "stem": "Boulders had sat wedged in the narrow gorge for centuries, but the sheer power of the flash flood was finally enough to ______ them, sending the massive stones tumbling downstream in a matter of seconds.", "choices": [{"text": "erode", "why": "Too broad: erode means to wear away gradually, but the flood knocked whole boulders loose in seconds, a sudden forceful removal.", "tag": "too-broad"}, {"text": "dislodge", "why": "The clue 'wedged... for centuries' plus 'enough to ___ them, sending the stones tumbling downstream' signals removing objects by force from a fixed position, the meaning of dislodge."}, {"text": "buttress", "why": "Reversed: buttress means to prop up or support in place, the opposite of forcing the boulders loose.", "tag": "reversed"}, {"text": "submerge", "why": "Unsupported: submerge means to cover with water, which says nothing about removing the wedged stones.", "tag": "unsupported"}], "answer": 1},
{"id": "vq-md-dismiss", "wordId": "md-dismiss", "skill": "words-in-context", "stem": "When Alfred Wegener first proposed that the continents had once been joined and had drifted apart, many established geologists were quick to ______ his idea as idle speculation, waving it aside without seriously weighing the evidence he had gathered.", "choices": [{"text": "endorse", "why": "Reversed: endorse means to support or approve, but the geologists rejected Wegener's idea.", "tag": "reversed"}, {"text": "scrutinize", "why": "Reversed: scrutinize means to examine closely, the opposite of waving the idea aside 'without seriously weighing the evidence.'", "tag": "reversed"}, {"text": "dismiss", "why": "The clue 'as idle speculation, waving it aside without seriously weighing the evidence' shows they rejected the idea as unworthy of consideration, the meaning of dismiss."}, {"text": "rebut", "why": "Too specific: rebut means to refute with a counterargument, but dismiss captures brushing the idea off without engaging it at all, as the passage stresses.", "tag": "too-specific"}], "answer": 2},
{"id": "vq-md-dispute", "wordId": "md-dispute", "skill": "words-in-context", "stem": "Even after Galileo published his observations, several astronomers continued to ______ his claim that Jupiter had moons, arguing forcefully that the specks he had recorded were nothing more than flaws in the glass of his primitive telescope.", "choices": [{"text": "corroborate", "why": "Reversed: corroborate means to confirm or support with evidence, but these astronomers were arguing against Galileo's claim.", "tag": "reversed"}, {"text": "dispute", "why": "The clue 'arguing forcefully that the specks were nothing more than flaws' shows the astronomers were challenging and contesting the claim, which is what dispute means."}, {"text": "dismiss", "why": "Too broad: dismiss means to reject outright without engaging, but the passage shows the astronomers actively arguing a counterexplanation, which is disputing.", "tag": "too-broad"}, {"text": "concede", "why": "Reversed: concede means to admit or accept as true, the opposite of resisting Galileo's claim.", "tag": "reversed"}], "answer": 1},
{"id": "vq-md-distraction-for", "wordId": "md-distraction-for", "skill": "words-in-context", "stem": "The nurse handed the child a brightly colored puzzle and used it as a ______ the frightened toddler, drawing her attention entirely to the shapes and colors so that the doctor could administer the vaccine before she even noticed the needle.", "choices": [{"text": "reward for", "why": "Unsupported: a reward is given in recognition of behavior, but the puzzle's purpose was to divert the child's attention, not to reward her.", "tag": "unsupported"}, {"text": "comfort for", "why": "True but irrelevant: comfort means solace, tempting because the child is frightened, but the passage stresses drawing her attention away, not soothing her feelings.", "tag": "true-but-irrelevant"}, {"text": "deterrent to", "why": "Reversed: a deterrent discourages an action, the opposite of engaging the toddler's attention with the puzzle.", "tag": "reversed"}, {"text": "distraction for", "why": "The clue 'drawing her attention entirely to the shapes... so the doctor could administer the vaccine before she noticed' shows something used to divert her focus, which is a distraction for her."}], "answer": 3},
{"id": "vq-md-epitomizing", "wordId": "md-epitomizing", "skill": "words-in-context", "stem": "Reviewers hailed the author's debut collection as ______ the spare aesthetic of literary minimalism, noting that each pared-down story distilled the movement's ideals of restraint and omission into their purest form.", "choices": [{"text": "repudiating", "why": "Repudiating means rejecting or disowning; the stories realize the movement's ideals rather than refusing them.", "tag": "reversed"}, {"text": "embellishing", "why": "Embellishing means adding decorative detail — the opposite of the 'pared-down' restraint and omission the passage describes.", "tag": "reversed"}, {"text": "epitomizing", "why": "Each story 'distilled the movement's ideals ... into their purest form,' so the collection serves as a perfect example of the aesthetic — the meaning of epitomizing."}, {"text": "anticipating", "why": "Anticipating implies coming before something; minimalism is an established movement with articulated ideals here, so the stories embody it rather than foreshadow it.", "tag": "unsupported"}], "answer": 2},
{"id": "vq-md-evolving", "wordId": "md-evolving", "skill": "words-in-context", "stem": "Ethnographers increasingly describe cultural traditions not as static inheritances passed down intact but as ______ practices, gradually reshaped as each generation reinterprets old rituals to fit new circumstances.", "choices": [{"text": "unchanging", "why": "Unchanging repeats the idea of 'static inheritances passed down intact,' which the sentence's 'not ... but' structure explicitly rejects.", "tag": "reversed"}, {"text": "vanishing", "why": "Vanishing means disappearing; the traditions are being transformed and carried forward, not lost.", "tag": "unsupported"}, {"text": "recurring", "why": "Recurring means happening again and again; traditions do repeat, but the contrast with 'static' demands change over time, not mere repetition.", "tag": "true-but-irrelevant"}, {"text": "evolving", "why": "The contrast marker 'not ... but' opposes 'static,' and 'gradually reshaped as each generation reinterprets' defines gradual development over time — the meaning of evolving."}], "answer": 3},
{"id": "vq-md-exactitude", "wordId": "md-exactitude", "skill": "words-in-context", "stem": "The nineteenth-century cartographer's coastal surveys were prized for their ______: repeated triangulations fixed each headland's position to within a few meters, and later satellite imaging confirmed the measurements almost point for point.", "choices": [{"text": "ambiguity", "why": "Ambiguity means openness to multiple interpretations; positions fixed 'to within a few meters' are the opposite of ambiguous.", "tag": "reversed"}, {"text": "grandeur", "why": "Grandeur means impressive scale or splendor; the passage praises the surveys' measurements, not their magnificence.", "tag": "unsupported"}, {"text": "exactitude", "why": "The colon elaborates with positions fixed 'to within a few meters' and later confirmed 'point for point,' so the blank must name the quality of precision."}, {"text": "thoroughness", "why": "Thoroughness is completeness of coverage; the clue concerns how precisely each point was fixed, not whether every feature was included.", "tag": "too-broad"}], "answer": 2},
{"id": "vq-md-exhilarating", "wordId": "md-exhilarating", "skill": "words-in-context", "stem": "Participants in the sports-psychology study consistently described their first white-water rafting run as ______, reporting surges of elation and heightened energy that persisted for hours after they left the river.", "choices": [{"text": "harrowing", "why": "Harrowing means acutely distressing; the participants report elation and energy, and nothing in the passage indicates distress.", "tag": "unsupported"}, {"text": "exhilarating", "why": "'Surges of elation and heightened energy' directly restates the meaning of exhilarating — making one feel elated and animated."}, {"text": "monotonous", "why": "Monotonous means dull and unvarying; a run that produces hours of elation is the opposite of tedious.", "tag": "reversed"}, {"text": "soothing", "why": "Soothing means calming; 'heightened energy' describes arousal and excitement, not relaxation.", "tag": "reversed"}], "answer": 1},
{"id": "vq-md-expand-on", "wordId": "md-expand-on", "skill": "words-in-context", "stem": "Responding to reviewers who found her first edition's central claim underdeveloped, the historian used the new preface to ______ her original argument, supplying two additional case studies and a fuller account of her sources.", "choices": [{"text": "expand on", "why": "Supplying 'additional case studies and a fuller account' answers the charge that the claim was 'underdeveloped' — she elaborates with further detail, the meaning of expand on."}, {"text": "gloss over", "why": "To gloss over is to pass by quickly without detail; adding case studies and fuller sourcing is the opposite of skimming past.", "tag": "reversed"}, {"text": "detract from", "why": "To detract from is to diminish something's force or value; the new material strengthens and develops the argument.", "tag": "reversed"}, {"text": "capitalize on", "why": "To capitalize on is to exploit something for advantage; the passage describes scholarly elaboration, not opportunistic gain.", "tag": "unsupported"}], "answer": 0},
{"id": "vq-md-encompass", "wordId": "md-encompass", "skill": "words-in-context", "stem": "Ecologists stress that a truly protected watershed must ______ not only the river itself but also the surrounding wetlands, forested slopes, and underground aquifers that feed it, since safeguarding one part while ignoring the rest accomplishes little.", "choices": [{"text": "bypass", "why": "Bypass means to go around or leave out, the opposite of holding all the elements within a protected area.", "tag": "reversed"}, {"text": "encompass", "why": "The watershed must hold the river 'and also' the wetlands, slopes, and aquifers within it, so the blank means to surround and include—encompass."}, {"text": "enumerate", "why": "Enumerate means to list one by one; the passage is about containing these features, not counting them.", "tag": "unsupported"}, {"text": "fragment", "why": "Fragment means to break into pieces, contradicting the call to keep the watershed's parts protected together.", "tag": "reversed"}], "answer": 1},
{"id": "vq-md-encourages", "wordId": "md-encourages", "skill": "words-in-context", "stem": "Studies of open-plan offices suggest that placing communal coffee stations at busy intersections ______ spontaneous collaboration, as employees who might never schedule a meeting end up trading ideas while waiting for the kettle.", "choices": [{"text": "permits", "why": "Permits means merely to allow; the stations actively prompt collaboration rather than just tolerating it.", "tag": "too-broad"}, {"text": "suppresses", "why": "Suppresses means to hold back, the opposite of fostering spontaneous exchanges of ideas.", "tag": "reversed"}, {"text": "mimics", "why": "Mimics means to imitate; nothing suggests the stations copy collaboration—they generate it.", "tag": "unsupported"}, {"text": "encourages", "why": "Employees who would never schedule a meeting end up trading ideas at the stations, so the design actively fosters collaboration—encourages."}], "answer": 3},
{"id": "vq-md-enduring", "wordId": "md-enduring", "skill": "words-in-context", "stem": "Though many bestselling novels of the 1850s were forgotten within a generation, Melville's work has proven surprisingly ______: it is still debated in classrooms and reinterpreted by artists more than a century and a half after its lukewarm initial reception.", "choices": [{"text": "fleeting", "why": "Fleeting means short-lived, contradicting a reputation still alive a century and a half later.", "tag": "reversed"}, {"text": "enduring", "why": "Unlike novels forgotten within a generation, Melville's work is still debated and reinterpreted long after publication, so the blank means lasting—enduring."}, {"text": "immutable", "why": "Immutable means incapable of change; yet the work is continually reinterpreted, so it is lasting, not unchanging.", "tag": "too-specific"}, {"text": "derivative", "why": "Derivative means imitative and unoriginal; the passage concerns the work's longevity, not its originality.", "tag": "unsupported"}], "answer": 1},
{"id": "vq-md-engulfs", "wordId": "md-engulfs", "skill": "words-in-context", "stem": "When a pyroclastic flow races down a volcano's flank, it ______ everything in its path within seconds, burying forests, roads, and entire villages beneath a searing avalanche of ash and gas.", "choices": [{"text": "engulfs", "why": "The flow buries forests, roads, and villages beneath ash within seconds, completely and overwhelmingly covering everything—engulfs."}, {"text": "spares", "why": "Spares means to leave unharmed, the opposite of burying everything in its path.", "tag": "reversed"}, {"text": "skirts", "why": "Skirts means to pass around the edge of; the flow overruns everything rather than avoiding it.", "tag": "reversed"}, {"text": "grazes", "why": "Grazes means to touch lightly; the intensity is far too weak for an avalanche that buries entire villages.", "tag": "too-broad"}], "answer": 0},
{"id": "vq-md-experiment-with", "wordId": "md-experiment-with", "skill": "words-in-context", "stem": "Rather than confining herself to the traditional orchestral palette she had mastered as a conservatory student, the young composer began to ______ unconventional sound sources such as dripping water, radio static, and prepared piano, weaving them into her mature symphonies.", "choices": [{"text": "adhere to", "why": "Means to stick rigidly to something, the opposite of the departure from tradition the passage describes.", "tag": "reversed"}, {"text": "dabble in", "why": "Implies casual, superficial engagement, but weaving the sounds into finished symphonies shows sustained, serious exploration.", "tag": "too-specific"}, {"text": "experiment with", "why": "The contrast with 'confining herself to' tradition shows she is now trying out new, unconventional materials, which is what to experiment with means."}, {"text": "conform to", "why": "Means to comply with an established convention, contradicting the passage's move away from the traditional palette.", "tag": "reversed"}], "answer": 2},
{"id": "vq-md-explains", "wordId": "md-explains", "skill": "words-in-context", "stem": "In her latest book, the geologist devotes an entire chapter to plate tectonics, in which she carefully ______ how the slow collision of continental plates over millions of years produces the towering mountain ranges that seem, to a casual observer, to have existed unchanged forever.", "choices": [{"text": "obscures", "why": "Means to make unclear or hide, the opposite of a chapter devoted to making the process understandable.", "tag": "reversed"}, {"text": "disputes", "why": "Means to challenge or deny; she is clarifying an accepted mechanism, not contesting it.", "tag": "unsupported"}, {"text": "describes", "why": "Recounts features but need not make the causal mechanism understandable; the phrase 'how...produces' demands clarifying why, which is what to explain does.", "tag": "too-broad"}, {"text": "explains", "why": "'How the slow collision...produces' signals she is making the causal process clear and understandable, the core sense of explains."}], "answer": 3},
{"id": "vq-md-exposed", "wordId": "md-exposed", "skill": "words-in-context", "stem": "The investigative reporter spent two years poring over leaked financial records, and her final series ______ a network of shell companies that powerful officials had used for decades to hide bribes from public scrutiny.", "choices": [{"text": "concealed", "why": "Means to hide, the opposite of what a revelatory investigative series does to a hidden network.", "tag": "reversed"}, {"text": "overlooked", "why": "Means failed to notice, but the reporter spent two years uncovering the network, not missing it.", "tag": "reversed"}, {"text": "exposed", "why": "The series brings a long-hidden network into public view, the core sense of exposed as made visible or known."}, {"text": "alleged", "why": "Means merely to assert without proof, but the documented records let her prove and lay bare the scheme, not just claim it.", "tag": "too-specific"}], "answer": 2},
{"id": "vq-md-extraordinary", "wordId": "md-extraordinary", "skill": "words-in-context", "stem": "What struck the biologists was not merely that the tiny songbird migrated, but the ______ scale of its journey: each autumn the four-inch creature crosses more than seven thousand miles of open ocean without once pausing to rest.", "choices": [{"text": "unremarkable", "why": "Means ordinary and not worth noting, contradicting the astonishment the feat produces in the biologists.", "tag": "reversed"}, {"text": "extraordinary", "why": "A four-inch bird flying seven thousand miles nonstop is exceptional and far beyond the usual, the meaning of extraordinary."}, {"text": "considerable", "why": "Means merely sizable; the colon's astonishing details call for a word meaning exceptional, not just large.", "tag": "too-broad"}, {"text": "adequate", "why": "Means just sufficient, a wrong dimension that says nothing about how remarkable the journey is.", "tag": "unsupported"}], "answer": 1},
{"id": "vq-md-fruitless", "wordId": "md-fruitless", "skill": "words-in-context", "stem": "After a decade of excavations that turned up nothing but empty trenches, the archaeologists finally conceded that their search for the lost city had been ______: not a single artifact confirmed that the fabled settlement had ever existed.", "choices": [{"text": "arduous", "why": "Too specific: arduous means demanding great effort; a dig can be arduous yet still succeed, so it misses the total absence of results.", "tag": "too-specific"}, {"text": "premature", "why": "Unsupported: premature means occurring too early, but nothing suggests the timing rather than the outcome was the problem.", "tag": "unsupported"}, {"text": "protracted", "why": "True but irrelevant: protracted means drawn out in time; the passage stresses the lack of any findings, not mere duration.", "tag": "true-but-irrelevant"}, {"text": "fruitless", "why": "'Nothing but empty trenches' and 'not a single artifact' establish that the search yielded no results, the meaning of fruitless.", "tag": ""}], "answer": 3},
{"id": "vq-md-fulfills", "wordId": "md-fulfills", "skill": "words-in-context", "stem": "The revised building code ______ every safety standard set by the international commission: inspectors confirmed that the design meets each required threshold exactly, neither falling short of nor surpassing the mandated specifications.", "choices": [{"text": "fulfills", "why": "'Meets each required threshold exactly' directly restates satisfying a requirement, which is what to fulfill a standard means.", "tag": ""}, {"text": "exceeds", "why": "Wrong intensity: to exceed is to surpass, but the passage says the design is 'neither ... surpassing' the specifications.", "tag": "too-specific"}, {"text": "neglects", "why": "Reversed: to neglect is to fail to meet, the opposite of satisfying every safety standard.", "tag": "reversed"}, {"text": "circumvents", "why": "Out of scope: to circumvent is to evade or get around a rule, not to meet its requirements.", "tag": "unsupported"}], "answer": 0},
{"id": "vq-md-grapple-with", "wordId": "md-grapple-with", "skill": "words-in-context", "stem": "In her later essays, the philosopher refused to offer easy answers; instead she chose to ______ the hardest paradoxes of free will, wrestling with contradictions that had defeated the sharpest thinkers for centuries.", "choices": [{"text": "dispense with", "why": "Reversed: to dispense with is to do away with or forgo, but she confronts the paradoxes rather than discarding them.", "tag": "reversed"}, {"text": "grapple with", "why": "'Wrestling with contradictions that had defeated the sharpest thinkers' signals struggling to deal with something difficult, the meaning of grapple with.", "tag": ""}, {"text": "comply with", "why": "Out of scope: to comply with is to obey a rule or demand; paradoxes are problems to struggle with, not commands.", "tag": "unsupported"}, {"text": "tamper with", "why": "Unsupported: to tamper with is to interfere or meddle improperly, not to struggle earnestly to understand a problem.", "tag": "unsupported"}], "answer": 1},
{"id": "vq-md-haphazard", "wordId": "md-haphazard", "skill": "words-in-context", "stem": "Unlike the carefully gridded streets of the planned capital, the old quarter had grown in a ______ fashion over the centuries, its lanes twisting without any pattern as each generation added structures wherever space happened to allow.", "choices": [{"text": "methodical", "why": "Reversed: methodical means orderly and systematic, the opposite of lanes twisting without any pattern.", "tag": "reversed"}, {"text": "hasty", "why": "Unsupported: hasty means hurried, but the disorder developed slowly over centuries, not from haste.", "tag": "unsupported"}, {"text": "uniform", "why": "Reversed: uniform means consistent and regular, but the quarter's lanes explicitly lack any pattern.", "tag": "reversed"}, {"text": "haphazard", "why": "The contrast with 'carefully gridded' plus 'twisting without any pattern ... wherever space happened to allow' signals disordered randomness, which is haphazard.", "tag": ""}], "answer": 3},
{"id": "vq-md-hoard", "wordId": "md-hoard", "skill": "words-in-context", "stem": "During periods of economic uncertainty, some households ______ essential goods, quietly amassing far more canned food and fuel than they could possibly use and storing the surplus away in cellars where no one else could reach it.", "choices": [{"text": "distribute", "why": "To distribute is to hand out or share among many, the opposite of the private amassing and concealing the passage describes.", "tag": "reversed"}, {"text": "hoard", "why": "The phrases 'amassing far more than they could use' and 'storing the surplus away' where no one can reach it exactly define accumulating and hiding valued goods."}, {"text": "squander", "why": "To squander is to waste or spend recklessly; this reverses the passage's emphasis on carefully saving and stockpiling.", "tag": "reversed"}, {"text": "catalog", "why": "To catalog is to list items systematically; the passage concerns amassing and concealing goods, not keeping an organized record of them.", "tag": "unsupported"}], "answer": 1},
{"id": "vq-md-imitated", "wordId": "md-imitated", "skill": "words-in-context", "stem": "The young painter so faithfully ______ the brushwork of the old masters that gallery visitors often mistook her practice canvases for genuine seventeenth-century originals, unable to detect where the reproduction diverged from its source.", "choices": [{"text": "imitated", "why": "'So faithfully... mistook her canvases for genuine originals' shows she copied the masters' work closely enough to resemble it."}, {"text": "critiqued", "why": "Critiqued means evaluated or reviewed; the passage is about reproducing the brushwork, not judging its merits.", "tag": "unsupported"}, {"text": "commissioned", "why": "Commissioned means formally ordered a work to be made, which misdescribes the painter's own act of copying the masters.", "tag": "unsupported"}, {"text": "surpassed", "why": "Surpassed means exceeded or outdid, but the passage emphasizes matching the originals so closely they were indistinguishable, not outdoing them.", "tag": "reversed"}], "answer": 0},
{"id": "vq-md-impede", "wordId": "md-impede", "skill": "words-in-context", "stem": "Engineers worried that the steady buildup of sediment would ______ the river's flow, gradually narrowing the channel and slowing the current until barges could no longer pass through the once-navigable passage.", "choices": [{"text": "accelerate", "why": "Accelerate means to speed up, the opposite of the slowing and narrowing the passage describes.", "tag": "reversed"}, {"text": "divert", "why": "Divert means to reroute or turn aside; it tempts in a river context but denotes changing direction, not hindering the flow's progress.", "tag": "too-specific"}, {"text": "impede", "why": "The details 'narrowing the channel and slowing the current' until barges cannot pass define hindering or obstructing movement."}, {"text": "purify", "why": "Purify means to cleanse or remove impurities; nothing in the passage concerns the cleanliness of the water, only its obstructed flow.", "tag": "unsupported"}], "answer": 2},
{"id": "vq-md-impending", "wordId": "md-impending", "skill": "words-in-context", "stem": "The barometer's sudden plunge and the eerie stillness of the air warned the sailors of an ______ storm, and they lashed down the rigging in anxious haste before the first violent gusts could strike the vessel.", "choices": [{"text": "elapsed", "why": "Elapsed means already passed, the opposite of a storm that is warned about and has not yet struck.", "tag": "reversed"}, {"text": "hypothetical", "why": "Hypothetical means merely supposed or imagined, but the concrete warning signs make the storm imminent rather than speculative.", "tag": "unsupported"}, {"text": "seasonal", "why": "Seasonal means recurring with the seasons; it describes a regular pattern, not something about to strike at any moment.", "tag": "too-specific"}, {"text": "impending", "why": "The warning signs and the rush to prepare 'before the first violent gusts could strike' show a threatening event about to happen."}], "answer": 3},
{"id": "vq-md-impenetrable", "wordId": "md-impenetrable", "skill": "words-in-context", "stem": "Even seasoned scholars of modernist literature describe Finnegans Wake as ______: James Joyce's multilingual puns and endlessly layered allusions have defeated generations of interpreters, some of whom concede that whole chapters resist any coherent reading at all.", "choices": [{"text": "ambiguous", "why": "Too weak: ambiguous means open to a few identifiable competing meanings, but the passage says whole chapters resist any coherent reading at all — total, not partial, obscurity.", "tag": "too-broad"}, {"text": "tedious", "why": "Tedious means boringly monotonous; the passage describes difficulty of understanding, not dullness — nothing suggests readers find the book boring.", "tag": "unsupported"}, {"text": "impenetrable", "why": "The colon introduces the elaboration — puns and allusions that 'defeated generations of interpreters' so that chapters 'resist any coherent reading' — so the blank must mean impossible to understand."}, {"text": "derivative", "why": "Derivative means imitative of others' work; the clues concern the book's incomprehensibility, and nothing in the passage concerns originality or imitation.", "tag": "unsupported"}], "answer": 2},
{"id": "vq-md-implication", "wordId": "md-implication", "skill": "words-in-context", "stem": "Although the 1867 charter never directly grants the governing council veto power, its exhaustive list of decisions requiring the council's assent carries the clear ______ that no major measure was meant to proceed without approval.", "choices": [{"text": "stipulation", "why": "Reversed: a stipulation is an explicitly stated condition, but the contrast marker 'Although... never directly grants' insists the charter does not state this outright.", "tag": "reversed"}, {"text": "implication", "why": "The passage contrasts what the charter 'never directly grants' with a conclusion drawn from its structure — a meaning conveyed without being stated, which is precisely an implication."}, {"text": "connotation", "why": "Too narrow a domain: a connotation is the emotional association a word carries, not an unstated logical conclusion that follows from a document's provisions.", "tag": "too-specific"}, {"text": "digression", "why": "A digression is a stray from the main topic; nothing in the passage concerns the charter wandering off subject.", "tag": "unsupported"}], "answer": 1},
{"id": "vq-md-improve-on", "wordId": "md-improve-on", "skill": "words-in-context", "stem": "Contemporary violin makers readily acknowledge the genius of Stradivari's instruments, yet many contend that modern acoustics research enables them to ______ his celebrated designs, producing violins that surpass the originals in evenness of projection.", "choices": [{"text": "adhere to", "why": "Reversed: adhering to the designs means following them exactly, which the clue rules out — the new violins 'surpass the originals,' so the designs must have been changed for the better.", "tag": "reversed"}, {"text": "capitalize on", "why": "Too general: capitalizing on the designs means merely exploiting them for advantage, missing the decisive clue that the results 'surpass the originals' — the designs themselves are made better.", "tag": "too-broad"}, {"text": "improve on", "why": "The appositive clue — 'producing violins that surpass the originals' — requires a phrase meaning to make something better than it was, which is exactly improve on."}, {"text": "account for", "why": "Account for means to explain; nothing in the passage concerns explaining why the designs work, only building better instruments from them.", "tag": "unsupported"}], "answer": 2},
{"id": "vq-md-incentive", "wordId": "md-incentive", "skill": "words-in-context", "stem": "Hoping to persuade skilled weavers and metalworkers to relocate within their walls, medieval town councils offered a decade's exemption from taxes; the ______ worked, and artisan quarters in such towns grew rapidly.", "choices": [{"text": "deterrent", "why": "Reversed: a deterrent discourages an action, but the exemption was offered 'hoping to persuade' artisans to come — it encouraged rather than discouraged.", "tag": "reversed"}, {"text": "incentive", "why": "The tax exemption was dangled to motivate a desired action — persuading artisans to relocate — which is the definition of an incentive; 'the ______ worked' confirms it succeeded in motivating them."}, {"text": "mandate", "why": "A mandate is an official requirement, but no one was compelled to move; the exemption invited a voluntary choice, which councils could only hope would succeed.", "tag": "unsupported"}, {"text": "reward", "why": "Too narrow: a reward compensates an action already completed, but the exemption was offered beforehand to induce relocation that had not yet happened.", "tag": "too-specific"}], "answer": 1},
{"id": "vq-md-indecipherable", "wordId": "md-indecipherable", "skill": "words-in-context", "stem": "The clay tablets bore a script with no known parallel, and although the incised symbols themselves were crisply preserved, epigraphers found the inscriptions utterly ______: no scholar could determine what any sequence of marks was meant to convey.", "choices": [{"text": "indecipherable", "why": "The colon elaborates that 'no scholar could determine what the marks were meant to convey,' so the blank must mean impossible to interpret or understand."}, {"text": "illegible", "why": "Illegible means physically impossible to read, but the passage says the symbols were 'crisply preserved'; the failure is one of meaning, not clarity.", "tag": "too-specific"}, {"text": "fragmentary", "why": "Fragmentary means broken or incomplete, yet the inscriptions are described as intact and well-preserved.", "tag": "unsupported"}, {"text": "pedestrian", "why": "Pedestrian means dull or unoriginal, a judgment of quality that nothing in the passage about untranslatable marks supports.", "tag": "unsupported"}], "answer": 0},
{"id": "vq-md-individualistic", "wordId": "md-individualistic", "skill": "words-in-context", "stem": "Rejecting the uniform aesthetic that dominated the studio, the young architect cultivated a strikingly ______ style: every building she designed bore idiosyncratic flourishes that no colleague would have dared to imitate.", "choices": [{"text": "individualistic", "why": "Her rejection of a uniform aesthetic and her 'idiosyncratic flourishes' mark the blank as expressing distinctive individuality and unconventionality."}, {"text": "derivative", "why": "Derivative means copied from others' work, contradicting flourishes 'no colleague would have dared to imitate.'", "tag": "reversed"}, {"text": "conventional", "why": "Conventional means ordinary and rule-following, the reverse of a style that rejects the dominant aesthetic.", "tag": "reversed"}, {"text": "utilitarian", "why": "Utilitarian stresses pure function over style, an emphasis the passage's focus on idiosyncratic expression does not support.", "tag": "unsupported"}], "answer": 0},
{"id": "vq-md-infallible", "wordId": "md-infallible", "skill": "words-in-context", "stem": "The philosopher warned against treating any scientific authority as ______: even the most rigorous experts, she noted, have occasionally been proven wrong, and a healthy discipline must stay open to correcting its own established conclusions.", "choices": [{"text": "fallible", "why": "Fallible means capable of error, but treating experts as fallible is precisely the openness she recommends, not the attitude she warns against.", "tag": "reversed"}, {"text": "omniscient", "why": "Omniscient means all-knowing, a matter of breadth of knowledge rather than the freedom from error the passage's 'proven wrong' pinpoints.", "tag": "unsupported"}, {"text": "provisional", "why": "Provisional means tentative and subject to revision, which aligns with her warning rather than the overconfidence she cautions against.", "tag": "reversed"}, {"text": "infallible", "why": "The reminder that even rigorous experts 'have been proven wrong' shows the blank means incapable of error or always correct."}], "answer": 3},
{"id": "vq-md-innovative", "wordId": "md-innovative", "skill": "words-in-context", "stem": "The choreographer's ______ approach broke sharply with tradition: she fused classical ballet with breakdancing and projected shifting digital imagery onto the dancers, combining techniques that no one in the company had ever attempted before.", "choices": [{"text": "derivative", "why": "'Derivative' means unoriginal or copied from others, the opposite of an approach 'no one had ever attempted before.'", "tag": "reversed"}, {"text": "meticulous", "why": "'Meticulous' means extremely careful about detail; the passage stresses novelty, not precision.", "tag": "unsupported"}, {"text": "innovative", "why": "'Broke sharply with tradition' and techniques 'no one had ever attempted before' signal the introduction of new, creative methods."}, {"text": "austere", "why": "'Austere' means severe or plain in style; nothing suggests the work was stark or unadorned.", "tag": "unsupported"}], "answer": 2},
{"id": "vq-md-insensible", "wordId": "md-insensible", "skill": "words-in-context", "stem": "After the fall from his horse, the knight lay ______ on the field for nearly an hour; when he finally regained awareness, he could recall neither the accident itself nor any of the moments that had immediately preceded it.", "choices": [{"text": "indignant", "why": "'Indignant' means angry at unfair treatment, a state that requires consciousness and is unsupported by the passage.", "tag": "unsupported"}, {"text": "impassive", "why": "'Impassive' means showing no emotion while fully aware; the phrase 'regained awareness' shows the knight had lost consciousness, not merely his expression.", "tag": "unsupported"}, {"text": "invulnerable", "why": "'Invulnerable' means incapable of being harmed, contradicting a knight who was injured by his fall.", "tag": "reversed"}, {"text": "insensible", "why": "Lying still until he 'regained awareness' and could 'recall nothing' establishes that he was unconscious."}], "answer": 3},
{"id": "vq-md-inspirational", "wordId": "md-inspirational", "skill": "words-in-context", "stem": "The activist's memoir became ______ for a generation of young organizers: readers repeatedly described how her account of perseverance against injustice moved them to overcome their own doubts and launch new campaigns in their communities.", "choices": [{"text": "inspirational", "why": "That the memoir 'moved them to overcome their doubts and launch new campaigns' shows it provided motivation and encouragement."}, {"text": "demoralizing", "why": "'Demoralizing' means draining confidence or hope, the reverse of a book that motivated readers to act.", "tag": "reversed"}, {"text": "controversial", "why": "'Controversial' means provoking public disagreement; the passage describes encouragement, not dispute.", "tag": "unsupported"}, {"text": "obligatory", "why": "'Obligatory' means required; nothing indicates readers were compelled to read the memoir.", "tag": "unsupported"}], "answer": 0},
{"id": "vq-md-intriguing", "wordId": "md-intriguing", "skill": "words-in-context", "stem": "The astronomers could not account for the faint, repeating radio pulse, yet they found it deeply ______: it raised questions that kept the entire team returning to the data night after night, eager to learn more.", "choices": [{"text": "alarming", "why": "Alarming implies fear or danger, but the passage describes eager curiosity, not dread.", "tag": "unsupported"}, {"text": "tedious", "why": "Tedious means dull and tiresome, the reverse of something that keeps a team eagerly returning.", "tag": "reversed"}, {"text": "intriguing", "why": "'Raised questions' and 'eager to learn more' describe aroused curiosity, which is precisely what intriguing means."}, {"text": "conclusive", "why": "Conclusive means settling a matter definitively, yet the passage stresses unanswered questions.", "tag": "reversed"}], "answer": 2},
{"id": "vq-md-invalidate", "wordId": "md-invalidate", "skill": "words-in-context", "stem": "In science a single reproducible counterexample can ______ an entire theory, compelling researchers to discard a framework that had once seemed unassailable and to build a new model from scratch.", "choices": [{"text": "substantiate", "why": "To substantiate is to confirm or support with evidence, the opposite of forcing a theory to be discarded.", "tag": "reversed"}, {"text": "summarize", "why": "To summarize is to condense the main points; it says nothing about rendering a theory void.", "tag": "unsupported"}, {"text": "complicate", "why": "To complicate merely makes something harder to follow; it falls short of nullifying a theory outright.", "tag": "too-broad"}, {"text": "invalidate", "why": "'Compelling researchers to discard a framework' shows the counterexample makes the theory void—the core meaning of invalidate."}], "answer": 3},
{"id": "vq-md-itinerary", "wordId": "md-itinerary", "skill": "words-in-context", "stem": "Before the expedition set out across the highlands, the guide handed each traveler a detailed ______ that laid out every day's destinations, the estimated hours of walking, and the villages where the group would stop to rest.", "choices": [{"text": "manifesto", "why": "A manifesto is a public declaration of aims or beliefs, not a day-by-day plan of a journey.", "tag": "unsupported"}, {"text": "itinerary", "why": "A document listing each day's destinations and stops along the route is the definition of an itinerary."}, {"text": "inventory", "why": "An inventory is a list of goods or supplies, not the planned course of travel described here.", "tag": "too-specific"}, {"text": "memoir", "why": "A memoir is a personal account written after events, whereas this document is prepared before the trip.", "tag": "unsupported"}], "answer": 1},
{"id": "vq-md-lacking", "wordId": "md-lacking", "skill": "words-in-context", "stem": "The soil samples explained why the seedlings had withered: the exhausted fields were entirely ______ the nitrogen that young plants must draw from the ground in order to grow strong stems and broad, healthy leaves.", "choices": [{"text": "harboring", "why": "Harboring means holding or possessing, the reverse of the deficiency that caused the seedlings to wither.", "tag": "reversed"}, {"text": "depleting", "why": "Depleting describes actively using something up, not the static absence of nitrogen the samples revealed.", "tag": "too-specific"}, {"text": "replenishing", "why": "Replenishing means refilling a supply, contradicting the passage's account of failed, nutrient-poor fields.", "tag": "reversed"}, {"text": "lacking", "why": "The withered seedlings and 'exhausted fields' show the soil is deficient in nitrogen—the meaning of lacking."}], "answer": 3},
{"id": "vq-md-legitimate", "wordId": "md-legitimate", "skill": "words-in-context", "stem": "After the bitterly disputed election, international observers spent weeks authenticating the ballots before finally declaring the new administration ______—the lawful and rightful authority to be recognized by every neighboring state.", "choices": [{"text": "provisional", "why": "Provisional means temporary or interim, whereas the passage certifies a lawful, established authority.", "tag": "too-specific"}, {"text": "autonomous", "why": "Autonomous means self-governing or independent, which the ballot verification does not address.", "tag": "unsupported"}, {"text": "legitimate", "why": "'The lawful and rightful authority' after ballots were authenticated names a government that is legitimate."}, {"text": "fraudulent", "why": "Fraudulent means obtained by deceit, the reverse of an administration certified as lawful.", "tag": "reversed"}], "answer": 2},
{"id": "vq-md-lonely", "wordId": "md-lonely", "skill": "words-in-context", "stem": "After her children moved abroad and her closest friends passed away, the widow described in the novel spends her evenings staring at the phone that never rings; the author renders her as profoundly ______, aching for the companionship that once filled her home.", "choices": [{"text": "lonely", "why": "The clue 'aching for the companionship that once filled her home' pins the blank to the feeling of isolation and lack of company."}, {"text": "solitary", "why": "Solitary merely means being alone, often by choice; it misses the emotional deprivation the passage stresses with 'aching for companionship.'", "tag": "too-broad"}, {"text": "secluded", "why": "Secluded describes a place that is hidden or private, not a person's yearning for company; wrong domain.", "tag": "too-specific"}, {"text": "indifferent", "why": "Indifferent means emotionally detached or uncaring, the opposite of a woman aching for connection.", "tag": "reversed"}], "answer": 0},
{"id": "vq-md-lucrative", "wordId": "md-lucrative", "skill": "words-in-context", "stem": "The spice trade of the fifteenth century proved so ______ that European monarchs financed perilous ocean voyages in pursuit of it: a single successful shipment of nutmeg or cloves could yield profits many times the cost of the expedition.", "choices": [{"text": "advantageous", "why": "Advantageous means generally beneficial but does not specifically denote producing income; the clue is about 'profits many times the cost.'", "tag": "too-broad"}, {"text": "lucrative", "why": "The elaboration 'could yield profits many times the cost' names financial profitability, which is exactly what lucrative means."}, {"text": "exorbitant", "why": "Exorbitant describes a price that is excessively high, not the profitability of a venture; wrong dimension.", "tag": "unsupported"}, {"text": "prohibitive", "why": "Prohibitive means so costly as to prevent an action, which would discourage rather than fund the voyages.", "tag": "reversed"}], "answer": 1},
{"id": "vq-md-manifest", "wordId": "md-manifest", "skill": "words-in-context", "stem": "Researchers studying infant development note that certain temperamental traits ______ themselves very early: babies as young as four months will visibly display the wariness or exuberance that comes to define their later personalities.", "choices": [{"text": "disguise", "why": "Disguise means to hide or mask, the opposite of the visible display the colon describes.", "tag": "reversed"}, {"text": "anticipate", "why": "Anticipate means to expect in advance; the passage is about traits being outwardly shown, not predicted.", "tag": "unsupported"}, {"text": "manifest", "why": "The colon's elaboration 'will visibly display the wariness or exuberance' matches manifest, to show a quality by one's acts or appearance."}, {"text": "induce", "why": "Induce means to bring about or cause; the passage describes traits appearing, not being triggered into existence.", "tag": "unsupported"}], "answer": 2},
{"id": "vq-md-mastery-over", "wordId": "md-mastery-over", "skill": "words-in-context", "stem": "By the time she was twenty, the young cellist had achieved such complete ______ the instrument that even the most technically demanding passages seemed effortless under her fingers.", "choices": [{"text": "mastery over", "why": "The result clause 'even the most technically demanding passages seemed effortless' signals command and proficiency, exactly mastery over."}, {"text": "aversion to", "why": "Aversion to means a strong dislike, which would not produce effortless, expert playing.", "tag": "reversed"}, {"text": "exposure to", "why": "Exposure to means mere contact or familiarity, which falls short of the command the effortlessness implies.", "tag": "too-broad"}, {"text": "reliance on", "why": "Reliance on means dependence; being dependent on the instrument says nothing about skill in playing it.", "tag": "unsupported"}], "answer": 0},
{"id": "vq-md-memoir", "wordId": "md-memoir", "skill": "words-in-context", "stem": "Unlike a novel, which invents its characters, or a biography, which studies its subject from the outside, a ______ recounts events the writer personally lived through, filtered entirely by the author's own recollection.", "choices": [{"text": "pamphlet", "why": "A pamphlet is a short persuasive tract, the wrong genre for a personal life account.", "tag": "unsupported"}, {"text": "synopsis", "why": "A synopsis is a brief summary of any work and need not be personal or lived through.", "tag": "too-broad"}, {"text": "depiction", "why": "A depiction is any representation; it lacks the first-person, lived-experience element the passage requires.", "tag": "too-broad"}, {"text": "memoir", "why": "The contrast with novel and biography plus 'recounts events the writer personally lived through... the author's own recollection' defines a memoir."}], "answer": 3},
{"id": "vq-md-minuscule", "wordId": "md-minuscule", "skill": "words-in-context", "stem": "Under the electron microscope, structures invisible to the naked eye come into focus; the researcher measured ______ pores in the cell membrane, each only a few nanometers across.", "choices": [{"text": "minuscule", "why": "'Invisible to the naked eye' and 'each only a few nanometers across' establish extremely small size, exactly minuscule."}, {"text": "negligible", "why": "Negligible stresses being too unimportant to count, but these pores are the important object of study, not insignificant.", "tag": "too-specific"}, {"text": "colossal", "why": "Colossal means enormous, the opposite of nanometer-scale pores.", "tag": "reversed"}, {"text": "intricate", "why": "Intricate describes complexity of structure, not size, which is the dimension the clue measures.", "tag": "unsupported"}], "answer": 0},
{"id": "vq-md-montage", "wordId": "md-montage", "skill": "words-in-context", "stem": "To compress years of the boxer's training into ninety seconds, the director relied on a ______: rapid cuts of predawn runs, sparring sessions, and dripping sweat were spliced together into one seamless, propulsive sequence.", "choices": [{"text": "caricature", "why": "A caricature is an exaggerated comic portrait, the wrong medium and technique for edited film.", "tag": "unsupported"}, {"text": "montage", "why": "'Rapid cuts... spliced together into one seamless sequence' is the film-editing technique of assembling separate shots, i.e., a montage."}, {"text": "tableau", "why": "A tableau is a single frozen, static scene, the opposite of the rapidly edited motion described.", "tag": "reversed"}, {"text": "synopsis", "why": "A synopsis is a plot summary, a description of content rather than an editing technique.", "tag": "too-broad"}], "answer": 1},
{"id": "vq-md-neglected", "wordId": "md-neglected", "skill": "words-in-context", "stem": "For decades after her death in 1960, Zora Neale Hurston's fiction was largely ______ by critics and publishers alike; only after Alice Walker's 1975 essay rekindled interest did her novels return to print and enter the American literary canon.", "choices": [{"text": "celebrated", "why": "Reversed: celebrated means widely praised, but the books were out of print and interest had to be 'rekindled'—the opposite of acclaim.", "tag": "reversed"}, {"text": "parodied", "why": "Parodied means mocked through imitation; nothing in the passage describes satire—only an absence of attention.", "tag": "unsupported"}, {"text": "neglected", "why": "The clue that interest had to be 'rekindled' before her novels could 'return to print' shows the work went ignored and uncared for—neglected."}, {"text": "suppressed", "why": "Too strong and narrow: suppressed implies deliberate prohibition or censorship, but the passage describes passive inattention, not an active campaign against the books.", "tag": "too-specific"}], "answer": 2},
{"id": "vq-md-ongoing", "wordId": "md-ongoing", "skill": "words-in-context", "stem": "Although the eruption that created Iceland's Surtsey island ceased in 1967, scientific study of the site is very much ______: researchers still return every summer to record how plants, seabirds, and insects continue to colonize the young volcanic terrain.", "choices": [{"text": "concluded", "why": "Reversed: concluded means finished, but researchers 'still return every summer' and colonization 'continue[s]'—the work is unfinished.", "tag": "reversed"}, {"text": "ongoing", "why": "The contrast marker 'Although the eruption... ceased' plus 'still return' and 'continue' shows the study persists—ongoing."}, {"text": "notional", "why": "Notional means existing only in theory, but the fieldwork actually happens each summer; the research is real, not hypothetical.", "tag": "unsupported"}, {"text": "preliminary", "why": "Precision failure: preliminary implies introductory groundwork before the main effort, but six decades of annual observation is the main research itself.", "tag": "too-specific"}], "answer": 1},
{"id": "vq-md-ornamental", "wordId": "md-ornamental", "skill": "words-in-context", "stem": "Restoration architects concluded that the villa's exterior colonnade is purely ______: the slender columns bear no structural load and were installed solely to evoke the grandeur of classical temples.", "choices": [{"text": "functional", "why": "Reversed: functional means serving a practical purpose, but the columns bear no load and exist only for appearance.", "tag": "reversed"}, {"text": "antiquated", "why": "Antiquated means old-fashioned or outdated; the colon explains the columns' purpose (decoration), not their age or datedness.", "tag": "unsupported"}, {"text": "monumental", "why": "Monumental means massive or imposing in scale; the passage describes 'slender' columns and concerns why they were added, not how large they are.", "tag": "unsupported"}, {"text": "ornamental", "why": "The colon elaborates the blank: the columns carry no structural load and were installed 'solely to evoke' grandeur — that is, they are purely decorative."}], "answer": 3},
{"id": "vq-md-overtly", "wordId": "md-overtly", "skill": "words-in-context", "stem": "Unlike earlier broadsides whose sponsors hid behind pseudonyms, the 1936 posters were ______ partisan: each named the party that commissioned it, displayed the party emblem, and made no attempt to disguise its persuasive intent.", "choices": [{"text": "covertly", "why": "Reversed: covertly means secretly — the practice of the earlier pseudonymous broadsides that the posters are explicitly contrasted against.", "tag": "reversed"}, {"text": "inadvertently", "why": "Inadvertently means accidentally; posters that name their commissioning party and display its emblem are partisan by deliberate design.", "tag": "unsupported"}, {"text": "marginally", "why": "Too weak: marginally means only slightly, but naming the party, showing its emblem, and hiding nothing make the partisanship thoroughgoing, not minimal.", "tag": "too-specific"}, {"text": "overtly", "why": "The contrast with hidden sponsors plus the colon's evidence — named party, displayed emblem, 'no attempt to disguise' — requires a word meaning openly, without concealment."}], "answer": 3},
{"id": "vq-md-pamphlet", "wordId": "md-pamphlet", "skill": "words-in-context", "stem": "In 1918, health officials distributed a sixteen-page ______ devoted to a single subject—influenza prevention—printed cheaply enough to hand out at streetcar stops and concise enough to be read in one sitting.", "choices": [{"text": "treatise", "why": "Too grand: a treatise is a lengthy, systematic scholarly work, at odds with a cheap sixteen-page handout readable in one sitting.", "tag": "too-broad"}, {"text": "pamphlet", "why": "Every clue — sixteen pages, a single subject, cheap printing, hand distribution — matches a small booklet on one topic, the definition of a pamphlet."}, {"text": "anthology", "why": "An anthology is a collection of works by various authors; a publication 'devoted to a single subject' is not a compilation.", "tag": "unsupported"}, {"text": "periodical", "why": "A periodical is published at regular intervals; nothing indicates recurring issues — this was a one-off handout for a single campaign.", "tag": "unsupported"}], "answer": 1},
{"id": "vq-md-perceive", "wordId": "md-perceive", "skill": "words-in-context", "stem": "Infants only a few months old can already ______ subtle differences between speech sounds that adults raised with other languages no longer notice, suggesting that the capacity to detect such fine distinctions is present very early in life.", "choices": [{"text": "fabricate", "why": "Fabricate means to invent or manufacture; infants are detecting existing differences, not making them up.", "tag": "unsupported"}, {"text": "articulate", "why": "Articulate means to express in words or produce clearly; the passage concerns detecting sounds, not producing them.", "tag": "too-specific"}, {"text": "perceive", "why": "The parallel phrases 'no longer notice' and 'the capacity to detect' show the blank must mean become aware of through the senses, which is what perceive means."}, {"text": "disregard", "why": "Disregard means to ignore, the reverse of the noticing and detecting the passage credits infants with.", "tag": "reversed"}], "answer": 2},
{"id": "vq-md-perpetual", "wordId": "md-perpetual", "skill": "words-in-context", "stem": "Near the poles of the Moon, certain crater floors lie in ______ shadow: because direct sunlight never reaches their depths, temperatures there have remained frigid without interruption across billions of years.", "choices": [{"text": "intermittent", "why": "Intermittent means starting and stopping at intervals, contradicting shadow that persists 'without interruption.'", "tag": "reversed"}, {"text": "perpetual", "why": "'Sunlight never reaches their depths' and 'without interruption across billions of years' establish shadow that never ends, which perpetual means."}, {"text": "prolonged", "why": "Prolonged means lasting a long time but eventually ending; the passage describes shadow that never lifts at all.", "tag": "too-specific"}, {"text": "fleeting", "why": "Fleeting means brief and quickly passing, the reverse of shadow enduring for billions of years.", "tag": "reversed"}], "answer": 1},
{"id": "vq-md-picturesque", "wordId": "md-picturesque", "skill": "words-in-context", "stem": "The village became a favorite subject for nineteenth-century landscape painters, who were drawn to its ______ charm: cobbled lanes, crooked timber cottages, and a moss-covered stone bridge that looked as though it had been lifted straight from a storybook.", "choices": [{"text": "austere", "why": "Austere means plain and severe, the opposite of the quaint, storybook charm the painters admired.", "tag": "reversed"}, {"text": "picturesque", "why": "The cobbled lanes, crooked cottages, and storybook bridge all describe a place that is charmingly and quaintly attractive, which picturesque means."}, {"text": "industrial", "why": "Industrial evokes factories and machinery, clashing with the rustic, pre-modern scene of cottages and a stone bridge.", "tag": "unsupported"}, {"text": "dilapidated", "why": "Dilapidated means fallen into ruin; the details are meant to seem charming, not decayed and neglected.", "tag": "too-specific"}], "answer": 1},
{"id": "vq-md-premeditated", "wordId": "md-premeditated", "skill": "words-in-context", "stem": "The prosecutor argued that the crime was ______ rather than impulsive: the defendant had purchased the weapon weeks earlier, studied the victim's daily schedule, and rehearsed a detailed escape route.", "choices": [{"text": "premeditated", "why": "The listed advance steps—buying the weapon weeks earlier, studying the schedule, rehearsing an escape—show it was planned beforehand, and the contrast 'rather than impulsive' confirms premeditated."}, {"text": "spontaneous", "why": "Means arising on impulse, which the passage explicitly rejects with 'rather than impulsive.'", "tag": "reversed"}, {"text": "negligent", "why": "Means careless or inattentive, but the described actions show careful planning, not carelessness.", "tag": "unsupported"}, {"text": "accidental", "why": "Means unintentional, contradicting the deliberate, methodical preparations the passage lists.", "tag": "reversed"}], "answer": 0},
{"id": "vq-md-prestige", "wordId": "md-prestige", "skill": "words-in-context", "stem": "Winning the award brought the young architect enormous ______: firms that had once ignored her now competed for her services, and her name alone lent credibility to any project it was attached to.", "choices": [{"text": "notoriety", "why": "Means fame for something bad, but the passage describes admiration and credibility, not disrepute.", "tag": "unsupported"}, {"text": "anonymity", "why": "Means the state of being unknown, the reverse of a celebrated, sought-after reputation.", "tag": "reversed"}, {"text": "prestige", "why": "The clue 'firms... competed for her services' and 'her name alone lent credibility' describes high reputation and esteem—prestige."}, {"text": "wealth", "why": "Refers to financial riches, which the passage never mentions; it emphasizes reputation and credibility, not income.", "tag": "true-but-irrelevant"}], "answer": 2},
{"id": "vq-md-profound", "wordId": "md-profound", "skill": "words-in-context", "domain": "literature", "difficulty": "medium", "targetSeconds": 45, "stem": "Reviewers noted that although the novella is barely a hundred pages long, its meditation on grief carries a ______ resonance: readers report returning to it year after year, discovering new layers of meaning with each rereading.", "choices": [{"text": "profound", "why": "The colon elaborates 'resonance' with 'new layers of meaning' and readers 'returning year after year,' signaling deep, lasting significance."}, {"text": "superficial", "why": "Reversed: it means shallow or surface-level, the opposite of the depth implied by discovering new layers of meaning over years.", "tag": "reversed"}, {"text": "fleeting", "why": "Wrong direction: it means short-lived or momentary, contradicting readers returning to the book year after year.", "tag": "reversed"}, {"text": "ornate", "why": "Out of scope: it describes elaborate decoration or style, not the depth of meaning the passage measures.", "tag": "unsupported"}], "answer": 0},
{"id": "vq-md-proponent-of", "wordId": "md-proponent-of", "skill": "words-in-context", "domain": "history", "difficulty": "medium", "targetSeconds": 50, "stem": "Throughout the 1840s, Dorothea Dix emerged as a tireless ______ humane treatment for the mentally ill, petitioning one legislature after another to fund hospitals in place of the prisons where such patients were then confined.", "choices": [{"text": "opponent of", "why": "Reversed: an opponent works against a cause, but Dix actively campaigned for humane treatment.", "tag": "reversed"}, {"text": "proponent of", "why": "Being 'tireless' and 'petitioning... to fund hospitals' shows she advocated and supported the cause."}, {"text": "chronicler of", "why": "Out of scope: a chronicler records events, whereas Dix pushed for change rather than merely documenting it.", "tag": "unsupported"}, {"text": "beneficiary of", "why": "Unsupported: a beneficiary receives an advantage, but the passage shows Dix championing others' welfare, not gaining from it.", "tag": "unsupported"}], "answer": 1},
{"id": "vq-md-protagonist", "wordId": "md-protagonist", "skill": "words-in-context", "domain": "literature", "difficulty": "medium", "targetSeconds": 45, "stem": "In Charlotte Bronte's novel, the orphaned governess is unmistakably the ______: nearly every scene unfolds through her eyes, and the narrative traces her moral growth from a powerless child into a self-possessed woman.", "choices": [{"text": "antagonist", "why": "Reversed: an antagonist is the opposing or hostile figure, not the central character whose growth the story follows.", "tag": "reversed"}, {"text": "bystander", "why": "Contradicted: a bystander is a passive onlooker, but every scene unfolds through this character and traces her development.", "tag": "unsupported"}, {"text": "protagonist", "why": "The clues 'nearly every scene unfolds through her eyes' and 'the narrative traces her moral growth' mark her as the leading character."}, {"text": "author", "why": "Wrong role: the author is the writer of the book (Bronte), not a character within its story.", "tag": "unsupported"}], "answer": 2},
{"id": "vq-md-provokes", "wordId": "md-provokes", "skill": "words-in-context", "domain": "science", "difficulty": "medium", "targetSeconds": 50, "stem": "For people with this rare sensitivity, even a trace of peanut protein ______ an immediate and severe immune response, as the body mistakes the harmless molecule for a dangerous invader and mobilizes its defenses at once.", "choices": [{"text": "prevents", "why": "Reversed: to prevent is to stop something from happening, the opposite of setting off an immune response.", "tag": "reversed"}, {"text": "resembles", "why": "Wrong sense: to resemble is merely to look like, carrying no causal force, yet the protein actively triggers the reaction.", "tag": "unsupported"}, {"text": "provokes", "why": "The body 'mistakes the molecule for a dangerous invader and mobilizes its defenses at once,' so the protein stimulates or incites the reaction."}, {"text": "withstands", "why": "Reversed: to withstand is to resist or endure, but the body reacts violently rather than holding firm.", "tag": "reversed"}], "answer": 2},
{"id": "vq-md-prudently", "wordId": "md-prudently", "skill": "words-in-context", "domain": "history", "difficulty": "medium", "targetSeconds": 50, "stem": "The widow managed the family estate so ______ that it survived three economic depressions intact: she kept ample reserves, refused every speculative venture, and never spent more in a year than the land reliably earned.", "choices": [{"text": "prudently", "why": "Keeping reserves, refusing speculation, and never overspending describe careful, risk-avoiding management."}, {"text": "recklessly", "why": "Reversed: recklessly means carelessly and with heedless risk, the opposite of her cautious strategy.", "tag": "reversed"}, {"text": "lavishly", "why": "Reversed: lavishly means extravagantly, contradicting a manager who never spent beyond earnings.", "tag": "reversed"}, {"text": "sparingly", "why": "Too narrow: sparingly denotes mere thrift, but refusing speculative ventures and holding reserves describe overall risk-avoidance, not just spending little.", "tag": "too-specific"}], "answer": 0},
{"id": "vq-md-question", "wordId": "md-question", "skill": "words-in-context", "domain": "science", "difficulty": "medium", "targetSeconds": 50, "stem": "The origin of the Moon remains an open ______ in planetary science: although the giant-impact hypothesis is widely favored, several features of the lunar rocks still lack a fully satisfying explanation, and researchers continue to investigate.", "choices": [{"text": "certainty", "why": "Reversed: a certainty is something definitely known, contradicting features that 'lack a fully satisfying explanation.'", "tag": "reversed"}, {"text": "dilemma", "why": "Imprecise: a dilemma is a forced choice between undesirable options, but the passage describes an unresolved matter of inquiry, not a choice.", "tag": "too-specific"}, {"text": "question", "why": "The word 'open,' the unexplained rock features, and researchers who 'continue to investigate' mark an unresolved matter of inquiry."}, {"text": "consensus", "why": "Reversed: a consensus is broad agreement, contradicting the passage's unresolved, still-investigated status.", "tag": "reversed"}], "answer": 2},
{"id": "vq-md-react-to", "wordId": "md-react-to", "skill": "words-in-context", "stem": "The biologist observed that the deep-sea organisms would ______ even the faintest change in water temperature, contracting their bodies within seconds of any shift, however slight, in their surroundings.", "choices": [{"text": "guard against", "why": "Reversed/defensive: it means to protect oneself from a threat, but the organisms actively respond to a stimulus rather than defend against one.", "tag": "reversed"}, {"text": "account for", "why": "Unsupported: it means to explain, a sense nothing in the passage points to; the organisms respond physically, they do not explain anything.", "tag": "unsupported"}, {"text": "react to", "why": "'Contracting their bodies within seconds of any shift' describes an immediate response to a stimulus, exactly what this phrase means."}, {"text": "adapt to", "why": "A near-synonym that fails on precision: adapting implies gradual accommodation over time, but the passage stresses an immediate response 'within seconds.'", "tag": "too-broad"}], "answer": 2},
{"id": "vq-md-rebuts", "wordId": "md-rebuts", "skill": "words-in-context", "stem": "In the closing chapter, the historian carefully ______ the traditional account of the treaty, marshaling newly discovered letters and financial records to show that the widely accepted explanation cannot withstand scrutiny.", "choices": [{"text": "corroborates", "why": "Reversed direction: it also uses evidence, but to confirm a claim, whereas the historian marshals records to disprove the accepted explanation.", "tag": "reversed"}, {"text": "qualifies", "why": "Too specific: it means to add reservations or limits, but the passage shows the account fully overturned, not merely moderated.", "tag": "too-specific"}, {"text": "summarizes", "why": "Too broad: it means merely to restate concisely, missing the argumentative work of disproving that 'cannot withstand scrutiny' requires.", "tag": "too-broad"}, {"text": "rebuts", "why": "Using new evidence 'to show that the widely accepted explanation cannot withstand scrutiny' is precisely to argue against and disprove a claim."}], "answer": 3},
{"id": "vq-md-recognizable", "wordId": "md-recognizable", "skill": "words-in-context", "stem": "Within just a few notes, the composer's style becomes instantly ______: the lush strings and abrupt key changes are so distinctive that listeners can identify her work even without being told who wrote it.", "choices": [{"text": "obscure", "why": "Reversed: it means hard to perceive or make out, the opposite of a style that can be identified within a few notes.", "tag": "reversed"}, {"text": "recognizable", "why": "'So distinctive that listeners can identify her work even without being told' names exactly the quality of being readily identified."}, {"text": "derivative", "why": "Unsupported: it means imitative of others, contradicting the passage's emphasis on how distinctive the style is.", "tag": "unsupported"}, {"text": "memorable", "why": "A near-synonym that fails on precision: it means easy to remember afterward, but the clue is instant identification on hearing, not lasting impression.", "tag": "too-broad"}], "answer": 1},
{"id": "vq-md-recognized-in", "wordId": "md-recognized-in", "skill": "words-in-context", "stem": "Even during her first year, the rare analytical talent ______ the young apprentice was so evident that her mentors singled her out as the student most likely to reshape the entire field.", "choices": [{"text": "concealed from", "why": "Reversed: this phrase means hidden away from, but the talent was 'so evident' that mentors plainly perceived it.", "tag": "reversed"}, {"text": "demanded of", "why": "Unsupported: it means required from a person, but the passage describes a talent perceived within her, not an expectation placed on her.", "tag": "unsupported"}, {"text": "recognized in", "why": "The talent being 'so evident' that mentors singled her out shows they identified and acknowledged that quality as present in her."}, {"text": "instilled in", "why": "A near-synonym phrase that fails on precision: it implies a trait gradually implanted by others, but the passage says the talent was already evident, merely perceived.", "tag": "too-specific"}], "answer": 2},
{"id": "vq-md-recommend", "wordId": "md-recommend", "skill": "words-in-context", "stem": "After reviewing the trial data, the panel of physicians declined to ban the drug outright but did ______ that it be prescribed only in low doses, advising caution until longer-term studies could confirm its safety.", "choices": [{"text": "mandate", "why": "A near-synonym that fails on intensity: it means to compel by rule, far stronger than the advisory tone set by 'advising caution.'", "tag": "too-broad"}, {"text": "prohibit", "why": "Reversed: it means to forbid, but the passage states the panel explicitly 'declined to ban the drug outright.'", "tag": "reversed"}, {"text": "guarantee", "why": "Unsupported: it means to promise an outcome, but the panel advises a cautious course rather than assuring results.", "tag": "unsupported"}, {"text": "recommend", "why": "'Advising caution' and advising that the drug be prescribed only in low doses is exactly to suggest a course as advisable."}], "answer": 3},
{"id": "vq-md-redress", "wordId": "md-redress", "skill": "words-in-context", "stem": "The new legislation was designed to ______ decades of unequal land distribution, returning territory to the families from whom it had been unjustly seized and compensating those who could no longer reclaim their ancestral homes.", "choices": [{"text": "perpetuate", "why": "Reversed: it means to prolong or continue, the opposite of correcting decades of injustice.", "tag": "reversed"}, {"text": "acknowledge", "why": "Too broad: it means merely to recognize the wrong, but the passage describes active remedy through returning land and compensation.", "tag": "too-broad"}, {"text": "document", "why": "Too specific: it means to record, but the legislation sets the injustice right rather than merely chronicling it.", "tag": "too-specific"}, {"text": "redress", "why": "'Returning territory... unjustly seized and compensating' those harmed is exactly to remedy and set right an unfair situation."}], "answer": 3},
{"id": "vq-md-redundant", "wordId": "md-redundant", "skill": "words-in-context", "stem": "After the company automated its billing system, several manual verification steps became ______: the software already performed those checks, so keeping the human reviews added nothing but wasted effort.", "choices": [{"text": "indispensable", "why": "Means absolutely necessary; this is the opposite of steps that 'added nothing,' so it reverses the meaning.", "tag": "reversed"}, {"text": "redundant", "why": "The colon explains that the software already did the checks and the reviews 'added nothing,' so the steps were unnecessary and superfluous."}, {"text": "erroneous", "why": "Means containing mistakes; the passage says the checks worked correctly and were merely duplicated, not wrong.", "tag": "unsupported"}, {"text": "provisional", "why": "Means temporary or interim; nothing suggests the steps were a trial arrangement.", "tag": "unsupported"}], "answer": 1},
{"id": "vq-md-refute", "wordId": "md-refute", "skill": "words-in-context", "stem": "The long-standing theory held that ulcers were caused solely by stress, but the researchers were able to ______ it by demonstrating that a specific bacterium was the true culprit, a finding that overturned decades of medical consensus.", "choices": [{"text": "refute", "why": "'Overturned decades of consensus' and identifying 'the true culprit' show the researchers disproved and contradicted the theory."}, {"text": "corroborate", "why": "Means to confirm or support with evidence; the researchers overturned the theory rather than backing it up.", "tag": "reversed"}, {"text": "popularize", "why": "Means to make widely known or liked; the passage is about proving the theory false, not spreading it.", "tag": "unsupported"}, {"text": "reformulate", "why": "Means to restate in a revised form; they discredited the theory outright rather than rephrasing it.", "tag": "unsupported"}], "answer": 0},
{"id": "vq-md-reinforcing", "wordId": "md-reinforcing", "skill": "words-in-context", "stem": "Before the earthquake retrofit, inspectors threaded thick steel cables throughout the old bridge, ______ its aging framework so that it could withstand far greater stress than its original design had ever allowed.", "choices": [{"text": "eroding", "why": "Means gradually wearing away; the cables make the framework stronger, not weaker, so this reverses the effect.", "tag": "reversed"}, {"text": "duplicating", "why": "Means making a copy; nothing in the passage is being copied, only strengthened.", "tag": "unsupported"}, {"text": "obscuring", "why": "Means hiding from view; the cables add strength rather than concealment.", "tag": "unsupported"}, {"text": "reinforcing", "why": "Because the bridge could then 'withstand far greater stress,' the cables were strengthening and supporting the framework."}], "answer": 3},
{"id": "vq-md-repressed-by", "wordId": "md-repressed-by", "skill": "words-in-context", "stem": "For decades the dissident press was ______ the authoritarian regime, which censored newspapers, jailed outspoken editors, and shut down any publication that dared to question official policy.", "choices": [{"text": "endorsed by", "why": "Means openly supported by; the regime crushed the press rather than backing it, so this reverses the relationship.", "tag": "reversed"}, {"text": "financed by", "why": "Means paid for by; the regime suppressed the press rather than funding it.", "tag": "reversed"}, {"text": "overlooked by", "why": "Means merely ignored; the regime actively censored and jailed, far more than failing to notice the press.", "tag": "unsupported"}, {"text": "repressed by", "why": "'Censored newspapers, jailed editors, and shut down any publication' shows the press was suppressed and held under control."}], "answer": 3},
{"id": "vq-md-resilience", "wordId": "md-resilience", "skill": "words-in-context", "difficulty": "hard", "stem": "Researchers studying children who thrive despite severe hardship point to ______ as the decisive trait: an ability to absorb painful setbacks and rebound from them rather than be permanently defeated by adversity.", "choices": [{"text": "resilience", "why": "Correct: 'absorb setbacks and rebound... rather than be permanently defeated' is precisely the capacity to recover from difficulty."}, {"text": "fragility", "why": "Reversed: fragility is the tendency to break easily, the opposite of rebounding from setbacks.", "tag": "reversed"}, {"text": "indifference", "why": "Indifference is a lack of interest or concern; nothing suggests these children are unconcerned about hardship.", "tag": "unsupported"}, {"text": "perseverance", "why": "Perseverance is steady, continued effort, but the clue emphasizes bouncing back after setbacks, which is the recovery meaning perseverance misses.", "tag": "too-broad"}], "answer": 0},
{"id": "vq-md-responsiveness-to", "wordId": "md-responsiveness-to", "skill": "words-in-context", "difficulty": "hard", "stem": "A sunflower's ______ light is remarkable: within hours of a passing cloud or a shifting shade, its broad leaves and heavy head reorient themselves to track the brightest source still available in the sky.", "choices": [{"text": "indifference to", "why": "Reversed: indifference means ignoring a stimulus, yet the plant actively reorients toward the light.", "tag": "reversed"}, {"text": "responsiveness to", "why": "Correct: the leaves and head 'reorient themselves to track' the light within hours, which is exactly reacting to a stimulus."}, {"text": "dependence on", "why": "Plants do depend on light to live, but the passage describes reacting to changing light, not the general need for it.", "tag": "true-but-irrelevant"}, {"text": "immunity to", "why": "Immunity means protection against something harmful; light is a stimulus the plant follows, not a threat it resists.", "tag": "unsupported"}], "answer": 1},
{"id": "vq-md-restored", "wordId": "md-restored", "skill": "words-in-context", "difficulty": "hard", "stem": "After decades of grime had darkened the chapel fresco, conservators painstakingly ______ it, lifting away centuries of soot and candle smoke until the original blues and golds shone as vividly as they had when first painted.", "choices": [{"text": "discarded", "why": "Reversed: to discard is to throw away, but the fresco was carefully cleaned and preserved, not disposed of.", "tag": "reversed"}, {"text": "embellished", "why": "To embellish is to add decoration; the conservators only removed soot to reveal what was already there, adding nothing.", "tag": "unsupported"}, {"text": "restored", "why": "Correct: 'the original blues and golds shone as vividly as when first painted' shows the fresco was returned to its original condition."}, {"text": "repainted", "why": "To repaint is to apply new paint over the surface, but they revealed the original paint by lifting soot rather than covering it.", "tag": "too-specific"}], "answer": 2},
{"id": "vq-md-ridicule", "wordId": "md-ridicule", "skill": "words-in-context", "difficulty": "hard", "stem": "When the young geologist first proposed that entire continents drift across the globe, established scientists did not merely doubt him; they ______ the idea, mocking it openly in their lectures and dismissing him as a hopeless fantasist.", "choices": [{"text": "endorsed", "why": "Reversed: to endorse is to support, yet the scientists mocked the idea and disparaged its author.", "tag": "reversed"}, {"text": "ridiculed", "why": "Correct: 'mocking it openly' and 'dismissing him as a fantasist' show they subjected the idea to contempt."}, {"text": "verified", "why": "Reversed: to verify is to confirm as true, but they were dismissing the idea, not proving it.", "tag": "reversed"}, {"text": "questioned", "why": "To question is merely to doubt, but the text says they 'did not merely doubt him,' so mild questioning is too weak.", "tag": "too-broad"}], "answer": 1},
{"id": "vq-md-rudimentary", "wordId": "md-rudimentary", "skill": "words-in-context", "difficulty": "hard", "stem": "The earliest known writing systems were ______: they could record little more than inventories of goods and simple tallies, lacking any means of capturing the grammar, tense, or subtle nuance of spoken language.", "choices": [{"text": "sophisticated", "why": "Reversed: sophisticated means highly developed and complex, but these systems could barely record simple tallies.", "tag": "reversed"}, {"text": "ornamental", "why": "Ornamental means decorative; the passage concerns the systems' limited capability, not any decorative purpose.", "tag": "unsupported"}, {"text": "fragmentary", "why": "Fragmentary means existing only in scattered, broken pieces, but the systems were whole and functional, just basic in what they could express.", "tag": "too-specific"}, {"text": "rudimentary", "why": "Correct: 'little more than inventories... simple tallies, lacking any means of capturing... nuance' describes a basic system limited to essentials."}], "answer": 3},
{"id": "vq-md-saturated-with", "wordId": "md-saturated-with", "skill": "words-in-context", "stem": "Critics observe that Derek Walcott's early poems are ______ maritime imagery: nets, tides, gull cries, and salt-bleached hulls appear in nearly every stanza, immersing readers in the sights and sounds of the Caribbean coast.", "choices": [{"text": "saturated with", "why": "The colon elaborates: sea images 'in nearly every stanza' that 'immerse' readers show the poems are thoroughly filled with — saturated with — maritime imagery."}, {"text": "devoid of", "why": "Devoid of means completely lacking — the opposite of imagery that appears in nearly every stanza.", "tag": "reversed"}, {"text": "derived from", "why": "Derived from would claim the poems originate in maritime imagery; the passage describes how pervasive the imagery is, not where the poems come from.", "tag": "unsupported"}, {"text": "confined to", "why": "Confined to would claim the poems contain nothing but maritime imagery; the passage says such imagery is pervasive, not that it is the poems' only content.", "tag": "too-broad"}], "answer": 0},
{"id": "vq-md-significant", "wordId": "md-significant", "skill": "words-in-context", "stem": "Although the two dialects differ in only a handful of vowel sounds, sociolinguists regard those differences as ______: speakers reliably deploy them to signal regional identity, and listeners infer social background from them within seconds.", "choices": [{"text": "negligible", "why": "Negligible means too small to matter; the colon shows the differences carry real social weight — the opposite of dismissible.", "tag": "reversed"}, {"text": "audible", "why": "Vowel differences are of course audible (able to be heard), but the colon glosses the blank in terms of social importance, not mere perceptibility.", "tag": "true-but-irrelevant"}, {"text": "pervasive", "why": "Pervasive means spread throughout, but the passage says the dialects differ in 'only a handful' of sounds — the differences are few, not widespread.", "tag": "unsupported"}, {"text": "significant", "why": "The contrast ('Although... only a handful') plus the colon — signaling identity and social background — shows the small differences are important and meaningful: significant."}], "answer": 3},
{"id": "vq-md-speculate", "wordId": "md-speculate", "skill": "words-in-context", "difficulty": "hard", "domain": "science", "targetSeconds": 45, "stem": "Because no direct fossil evidence of the creature's diet has ever been recovered, paleontologists can only ______ about what the animal ate, proposing tentative ideas that remain wholly untethered to firm proof.", "choices": [{"text": "speculate", "why": "\"only\" plus \"tentative ideas\" and \"untethered to firm proof\" demands a verb meaning to conjecture without evidence."}, {"text": "ascertain", "why": "To ascertain is to establish with certainty, the opposite of the passage's admission that no firm proof exists.", "tag": "reversed"}, {"text": "corroborate", "why": "To corroborate is to confirm with supporting evidence, but the sentence stresses that such evidence has never been recovered.", "tag": "reversed"}, {"text": "catalog", "why": "To catalog is to list systematically; nothing in the passage describes compiling or recording items.", "tag": "unsupported"}], "answer": 0},
{"id": "vq-md-speculated", "wordId": "md-speculated", "skill": "words-in-context", "difficulty": "hard", "domain": "history-of-science", "targetSeconds": 45, "stem": "In a letter written long before telescopes could settle the matter, the astronomer ______ that the distant points of light might be suns like our own—an idea she offered merely as a guess, with no means of testing it at the time.", "choices": [{"text": "demonstrated", "why": "To demonstrate is to prove conclusively, contradicting \"merely as a guess\" with \"no means of testing it.\"", "tag": "reversed"}, {"text": "speculated", "why": "\"offered merely as a guess\" with \"no means of testing it\" signals forming a theory without firm evidence."}, {"text": "confirmed", "why": "To confirm is to establish as true, but the letter predates any ability to verify the claim.", "tag": "reversed"}, {"text": "recorded", "why": "To record is simply to set down information; it misses the conjectural, guessing sense the clues require.", "tag": "unsupported"}], "answer": 1},
{"id": "vq-md-standard", "wordId": "md-standard", "skill": "words-in-context", "difficulty": "hard", "domain": "history-of-technology", "targetSeconds": 45, "stem": "Before the industrial era, each workshop forged screws to its own dimensions; the adoption of a single, universally accepted ______ meant that a bolt made in one city would at last fit a nut manufactured in another.", "choices": [{"text": "standard", "why": "\"single, universally accepted\" measure that lets parts from different cities fit names an agreed norm or criterion."}, {"text": "exception", "why": "An exception is a departure from the norm, the reverse of a shared rule that unifies dimensions.", "tag": "reversed"}, {"text": "variation", "why": "Variation denotes difference and divergence, the very problem the sentence says was overcome.", "tag": "reversed"}, {"text": "estimate", "why": "An estimate is a rough approximation, but interchangeable parts require an exact, fixed measure, not a guess.", "tag": "unsupported"}], "answer": 0},
{"id": "vq-md-stylistic", "wordId": "md-stylistic", "skill": "words-in-context", "difficulty": "hard", "domain": "literature", "targetSeconds": 45, "stem": "The two translations convey exactly the same plot, so their differences are largely ______: one renders the prose in short, clipped sentences, while the other favors long, ornate clauses and deliberately archaic diction.", "choices": [{"text": "factual", "why": "Factual differences concern content, but the passage says the plot is identical and only the manner of expression varies.", "tag": "unsupported"}, {"text": "stylistic", "why": "Identical plot with contrasts in sentence length, ornamentation, and diction locates the differences in literary style."}, {"text": "thematic", "why": "Thematic differences involve subject or meaning, whereas the contrast here is purely in phrasing and diction.", "tag": "unsupported"}, {"text": "trivial", "why": "Trivial judges importance, not the kind of difference; the sentence characterizes what differs, not how much it matters.", "tag": "unsupported"}], "answer": 1},
{"id": "vq-md-subsequent", "wordId": "md-subsequent", "skill": "words-in-context", "difficulty": "hard", "domain": "history-of-science", "targetSeconds": 45, "stem": "The initial 1905 paper presented the theory only in rough outline; its full mathematical form appeared in ______ articles that the physicist published over the following three years.", "choices": [{"text": "preceding", "why": "Preceding means coming before, the reverse of articles published \"over the following three years.\"", "tag": "reversed"}, {"text": "concurrent", "why": "Concurrent means occurring at the same time, contradicting a sequence spread across the years after 1905.", "tag": "unsupported"}, {"text": "subsequent", "why": "An \"initial 1905 paper\" followed by articles \"over the following three years\" marks them as later, following works."}, {"text": "hypothetical", "why": "Hypothetical means imagined or supposed, but these are real articles the physicist actually published.", "tag": "unsupported"}], "answer": 2},
{"id": "vq-md-subsurface", "wordId": "md-subsurface", "skill": "words-in-context", "difficulty": "hard", "targetSeconds": 45, "stem": "The radar aboard the orbiter cannot photograph what lies beneath the Martian crust, but by measuring how its signals bounce back it can map ______ features — buried channels, ice deposits, and ancient lava tubes hidden many meters below the visible terrain.", "choices": [{"text": "subsurface", "why": "The clues 'beneath the Martian crust,' 'buried,' and 'below the visible terrain' point to features lying in the strata below the ground."}, {"text": "superficial", "why": "Means lying on or near the surface — the opposite of features hidden many meters underground.", "tag": "reversed"}, {"text": "atmospheric", "why": "Pertains to the layer of gases above a planet's surface, not the rock and ice below it.", "tag": "unsupported"}, {"text": "peripheral", "why": "Means at the outer edge or margin; the passage locates the features by depth (below), not by edge position.", "tag": "too-specific"}], "answer": 0},
{"id": "vq-md-subversive", "wordId": "md-subversive", "skill": "words-in-context", "difficulty": "hard", "targetSeconds": 45, "stem": "On its surface the children's fable seemed harmless, but censors quickly recognized its ______ intent: beneath the talking animals lay a pointed attack on the monarchy and an unmistakable call to overturn the established order.", "choices": [{"text": "conformist", "why": "Means compliant with prevailing rules; the fable seeks to overturn the established order, not uphold it.", "tag": "reversed"}, {"text": "didactic", "why": "Means intended to instruct or moralize; a fable often is, but the clue names an attack on the monarchy and a call to revolt, not mere teaching.", "tag": "true-but-irrelevant"}, {"text": "subversive", "why": "The 'attack on the monarchy' and 'call to overturn the established order' identify an intent to undermine existing institutions."}, {"text": "sentimental", "why": "Means marked by tender emotion; nothing in the passage points to emotional appeal.", "tag": "unsupported"}], "answer": 2},
{"id": "vq-md-susceptible-to", "wordId": "md-susceptible-to", "skill": "words-in-context", "stem": "Because seedlings raised in sterile laboratory conditions never develop the protective microbial communities that normally coat plants grown outdoors, they remain unusually ______ common fungal infections once they are transplanted into ordinary garden soil.", "choices": [{"text": "immune to", "why": "'Immune to' means resistant, the reverse of what plants lacking protective microbes would be.", "tag": "reversed"}, {"text": "indifferent to", "why": "'Indifferent to' denotes emotional unconcern, which cannot apply to a seedling's physical vulnerability to infection.", "tag": "unsupported"}, {"text": "susceptible to", "why": "'Never develop the protective... communities' establishes vulnerability, and 'susceptible to' means likely to be affected or harmed by something."}, {"text": "superior to", "why": "'Superior to' compares quality or rank, which does not describe how prone the seedlings are to catching an infection.", "tag": "unsupported"}], "answer": 2},
{"id": "vq-md-tedious", "wordId": "md-tedious", "skill": "words-in-context", "stem": "Before computers automated the calculations, mapping a single star chart required astronomers to perform the same arithmetic thousands of times by hand—work so ______ that assistants often lost their concentration halfway through the endless columns of identical figures.", "choices": [{"text": "exhilarating", "why": "'Exhilarating' means thrilling, the opposite of work that makes assistants lose concentration.", "tag": "reversed"}, {"text": "intricate", "why": "'Intricate' means complex, but the problem here is dull repetition, not difficulty of the calculation.", "tag": "too-specific"}, {"text": "hazardous", "why": "'Hazardous' means dangerous, which has no basis in a passage about monotonous arithmetic.", "tag": "unsupported"}, {"text": "tedious", "why": "'The same arithmetic thousands of times' and 'endless columns' causing lost concentration define 'tedious,' meaning tiresome from monotony."}], "answer": 3},
{"id": "vq-md-topography", "wordId": "md-topography", "skill": "words-in-context", "stem": "Before designing the mountain railway, engineers spent months surveying the region's ______, charting every ridge, ravine, and change in elevation so that the track could be routed around the steepest and most unstable slopes.", "choices": [{"text": "climate", "why": "'Climate' refers to weather patterns, not the shape of the land the engineers were charting.", "tag": "unsupported"}, {"text": "vegetation", "why": "'Vegetation' is plant cover, but the surveyors mapped ridges, ravines, and elevation, not flora.", "tag": "too-specific"}, {"text": "geology", "why": "'Geology' concerns the composition and structure of rock, whereas the passage tracks surface contours and elevation.", "tag": "too-specific"}, {"text": "topography", "why": "'Charting every ridge, ravine, and change in elevation' describes 'topography,' the surface shape and features of the land."}], "answer": 3},
{"id": "vq-md-transcend", "wordId": "md-transcend", "skill": "words-in-context", "stem": "Great works of art, the critic argued, are never confined to the era that produced them; a true masterpiece can ______ the particular customs and controversies of its own age and speak just as powerfully to audiences centuries later.", "choices": [{"text": "transcend", "why": "'Never confined to the era' and still speaking 'centuries later' match 'transcend,' meaning to rise beyond the limits of something."}, {"text": "reflect", "why": "'Reflect' means to mirror its own age, but the passage insists the work is not confined to that age—it goes beyond it.", "tag": "too-specific"}, {"text": "undermine", "why": "'Undermine' means to weaken or sabotage, which does not fit a work that endures and communicates across time.", "tag": "unsupported"}, {"text": "preserve", "why": "'Preserve' means to keep intact, missing the idea of surpassing the limits of one's own era.", "tag": "unsupported"}], "answer": 0},
{"id": "vq-md-transcending", "wordId": "md-transcending", "skill": "words-in-context", "stem": "What impressed the panel was the athlete's ability to keep ______ every limit that trainers had once thought fixed, breaking records that had stood for decades and redefining what the human body was assumed capable of.", "choices": [{"text": "respecting", "why": "'Respecting' a limit means staying within it, the opposite of breaking long-standing records.", "tag": "reversed"}, {"text": "transcending", "why": "'Breaking records' and 'redefining what the body was capable of' describe 'transcending'—surpassing and rising above fixed limits."}, {"text": "recording", "why": "'Recording' means noting something down, which has nothing to do with exceeding physical limits.", "tag": "unsupported"}, {"text": "approaching", "why": "'Approaching' a limit means coming near without passing it, but the athlete actually broke the records, exceeding the limits.", "tag": "too-specific"}], "answer": 1},
{"id": "vq-md-uniform", "wordId": "md-uniform", "skill": "words-in-context", "stem": "For the optical experiment to yield valid results, the reflective coating applied to each lens had to be perfectly ______: even a slight difference in thickness from one sample to the next would have distorted the measurements of how much light passed through.", "choices": [{"text": "erratic", "why": "Means irregular and unpredictable; the requirement is that samples not vary, so this reverses the needed quality.", "tag": "reversed"}, {"text": "uniform", "why": "Because 'even a slight difference in thickness from one sample to the next' would ruin the data, the coating must be consistent and unvarying."}, {"text": "porous", "why": "Means full of tiny holes; the concern is even thickness across samples, not the material's permeability.", "tag": "unsupported"}, {"text": "durable", "why": "Means long-lasting; toughness has no bearing on the sample-to-sample consistency the experiment demands.", "tag": "true-but-irrelevant"}], "answer": 1},
{"id": "vq-md-useful", "wordId": "md-useful", "skill": "words-in-context", "stem": "When chemists first isolated an enzyme from a plastic-eating bacterium in 2016, some dismissed it as a laboratory curiosity. It has since proved remarkably ______ : engineers now deploy modified versions of the enzyme in recycling facilities to break down polyester waste that once resisted treatment.", "choices": [{"text": "ornamental", "why": "Unsupported: ornamental means decorative; nothing in the passage attributes aesthetic value to the enzyme.", "tag": "unsupported"}, {"text": "profitable", "why": "Too narrow: profitable means generating financial gain; the passage describes practical application in recycling, saying nothing about earnings.", "tag": "too-specific"}, {"text": "obsolete", "why": "Reversed: obsolete means outdated and no longer employed; the enzyme is only now being put to work.", "tag": "reversed"}, {"text": "useful", "why": "The colon supplies the clue — engineers deploy the enzyme to break down waste, a concrete practical purpose, so the blank must mean serving a purpose."}], "answer": 3},
{"id": "vq-md-validated", "wordId": "md-validated", "skill": "words-in-context", "stem": "Physicists greeted the 1916 prediction of gravitational waves with skepticism for nearly a century. The theory was finally ______ in 2015, when the LIGO observatories recorded a signal from colliding black holes that matched the predicted waveform almost exactly.", "choices": [{"text": "contradicted", "why": "Reversed: contradicted means shown to be false; the recorded signal matched the prediction, confirming rather than refuting it.", "tag": "reversed"}, {"text": "examined", "why": "Too weak: examined means merely studied or tested; the clue — a signal matching the prediction 'almost exactly' — indicates confirmation, not mere scrutiny.", "tag": "too-broad"}, {"text": "validated", "why": "The clue is decisive: an observed signal matching the predicted waveform proves the theory true, i.e., confirms it."}, {"text": "popularized", "why": "Unsupported: popularized means made widely known to the public; the passage concerns experimental evidence, not publicity.", "tag": "unsupported"}], "answer": 2},
{"id": "vq-md-virtuoso", "wordId": "md-virtuoso", "skill": "words-in-context", "stem": "Contemporaries regarded pianist Art Tatum as a ______ : his recordings feature runs of such speed and harmonic daring that fellow musicians, hearing them for the first time, sometimes insisted that two pianists must have been playing at once.", "choices": [{"text": "novice", "why": "Reversed: a novice is a beginner; playing that seemed to require two performers indicates supreme mastery, not inexperience.", "tag": "reversed"}, {"text": "patron", "why": "Wrong role: a patron financially supports the arts; Tatum is described performing, not funding performances.", "tag": "unsupported"}, {"text": "enthusiast", "why": "Too weak: an enthusiast merely loves an activity; the clue — feats so skilled listeners suspected two players — demands exceptional ability, not fondness.", "tag": "too-broad"}, {"text": "virtuoso", "why": "The colon's clue — technical feats so dazzling that musicians thought two pianists were playing — identifies a performer of the highest skill."}], "answer": 3},
{"id": "vq-md-virtuousness", "wordId": "md-virtuousness", "skill": "words-in-context", "stem": "In her fiction, George Eliot repeatedly suggests that genuine ______ consists not in conspicuous public piety but in small, unrecorded acts of kindness performed with no expectation of recognition — right conduct pursued purely for its own sake.", "choices": [{"text": "propriety", "why": "Wrong target: propriety means conformity to outward social conventions, which the passage explicitly discounts ('not in conspicuous public piety').", "tag": "too-specific"}, {"text": "virtuousness", "why": "The dash's restatement — 'right conduct pursued purely for its own sake' — defines the quality of doing what is right."}, {"text": "notoriety", "why": "Reversed: notoriety means being widely known, typically for ill; the passage prizes acts that go entirely unrecognized.", "tag": "reversed"}, {"text": "eloquence", "why": "Unsupported: eloquence is skill with language; nothing in the passage concerns speech or writing.", "tag": "unsupported"}], "answer": 1},
{"id": "vq-md-waive", "wordId": "md-waive", "skill": "words-in-context", "stem": "Hoping to draw applicants from low-income households, the university announced that it would ______ its eighty-five-dollar application fee for any student demonstrating financial need, so that qualifying candidates pay nothing at all to apply.", "choices": [{"text": "impose", "why": "Reversed: impose means to establish or levy a charge; the policy removes the cost rather than creating it.", "tag": "reversed"}, {"text": "refund", "why": "Wrong sequence: refund means to return money already collected; here the fee is never charged in the first place.", "tag": "too-specific"}, {"text": "waive", "why": "The clue 'qualifying candidates pay nothing at all' shows the university voluntarily giving up its claim to the fee."}, {"text": "reduce", "why": "Too weak: reduce means to lessen; a reduced fee would still cost something, but the passage says applicants pay nothing.", "tag": "too-broad"}], "answer": 2},
{"id": "vq-md-withdraw", "wordId": "md-withdraw", "skill": "words-in-context", "stem": "After laboratories on three continents failed to reproduce the study's central finding, the journal's editors asked the authors to ______ the paper entirely, striking it from the scientific record rather than merely issuing a correction.", "choices": [{"text": "withdraw", "why": "The appositive clue — 'striking it from the scientific record' — means taking the paper back entirely, i.e., removing or retracting it."}, {"text": "revise", "why": "Contradicted: revise means to amend a text that stays published, but the passage rejects that path — removal 'rather than merely issuing a correction.'", "tag": "unsupported"}, {"text": "circulate", "why": "Reversed: circulate means to distribute more widely — the opposite of striking the paper from the record.", "tag": "reversed"}, {"text": "annotate", "why": "Unsupported: annotate means to add explanatory notes; nothing suggests supplementing the paper, which is being removed.", "tag": "unsupported"}], "answer": 0}
);
